window.GUIDE=window.GUIDE||{};GUIDE.tr=[];
GUIDE.tr.push({n:1,t:"건강",en:"Sağlık",units:[
{n:1,t:"건강에 좋은 음식",g:[
{f:"-다가 보니까",en:"X'i yapa yapa / yaparken Y'yi fark ettim, Y oldu",
core:"Bir şeyi sürekli ya da tekrar tekrar yaptınız ve bunun sonucunda bir şey fark ettiniz veya yeni bir duruma geldiniz. 보니까 kısmı “geriye bakınca anladım ki” anlamını taşır. Bir neden-keşif kalıbıdır. Türkçedeki “yede yede”, “yaşaya yaşaya” gibi tekrarlı zarf-fiillere benzer.",
forms:[["Fiil","먹다(가) 보니까 · 살다(가) 보니까 · 만들다(가) 보니까"]],
rules:["Yalnızca fiillerle kullanılır; konuşmada 가 sık sık düşer: <b>먹다 보니까</b>.",
"X cümlesinde zaman eki olmaz: asla 먹었다가 보니까 denmez.",
"Y cümlesi bir keşfi ya da sonucu bildirir, genellikle geçmiş ya da şimdiki zamanda: -었어요, -게 됐어요, -더라고요, -네요.",
"X eylemi zamana yayılan ya da tekrarlanan bir eylemdir. Bu yüzden 자주, 매일, 계속 ile sık kullanılır.",
"<b>-다가 보면</b> (5과) ile karıştırmayın; o genel bir tahmindir: “X'i yapmaya devam edersen Y olur.” -다 보니까 ise zaten olmuş bir şeyi anlatır."],
ex:[["매일 잡곡밥을 **먹다 보니까** 이제는 흰쌀밥이 맛이 없어요.","Her gün karışık tahıllı pilav yiye yiye artık beyaz pirinç bana tatsız geliyor."],
["혼자 **살다 보니까** 요리 실력이 늘었어요.","Yalnız yaşaya yaşaya yemek yapmada ilerledim."],
["친구와 이야기를 **하다 보니까** 벌써 밤 12시가 됐어요.","Arkadaşımla sohbet ederken bir baktım, gece yarısı olmuş."]]},
{f:"-을 겸",en:"hem X hem de Y için; aynı zamanda … olarak",
core:"Tek bir eylemi aynı anda iki (veya daha fazla) amaçla yaparsınız. Kalıbın tam hâli <b>-(으)ㄹ 겸 -(으)ㄹ 겸</b> şeklindedir ve isimlerle de kullanılır: <b>N 겸 N</b>.",
forms:[["Fiil, 받침 yok","볼 겸 · 쉴 겸 (ㄹ ile biten gövde: 살다 → 살 겸)"],["Fiil, 받침 var","먹을 겸 · 읽을 겸"],["İsim","아침 겸 점심 (= brunch, kahvaltı-öğle yemeği) · 운동 겸 산책"]],
rules:["Genellikle ardından bir hareket ya da eylem fiili gelir: 가다, 오다, 나가다, 하다.",
"İki amaç: <b>운동도 할 겸 친구도 만날 겸</b> (her birine 도 eklenir). Tek amaç söylenirse, söylenmemiş bir amaç daha olduğu ima edilir.",
"Yalnızca fiillerle kullanılır, sıfatlarla kullanılmaz. 겸 cümlesinde zaman eki olmaz.",
"N 겸 N iki işlevi olan bir şeyi de anlatır: 거실 겸 서재 (aynı zamanda çalışma odası olan oturma odası)."],
ex:[["운동도 **할 겸** 장도 **볼 겸** 시장까지 걸어갔어요.","Hem biraz egzersiz yapmak hem de alışveriş yapmak için pazara kadar yürüdüm."],
["건강도 **챙길 겸** 직접 밥상을 차려 먹기로 했어요.","Biraz da sağlığıma dikkat etmek için yemeklerimi kendim hazırlamaya karar verdim."],
["늦게 일어나서 **아침 겸 점심**으로 비빔밥을 먹었어요.","Geç kalktım, kahvaltı-öğle yemeği olarak bibimbap yedim."]]}],
v:[["밥상","yemek masası, sofra; kurulmuş sofra","Sadece mobilyayı değil, üzerine dizilmiş yemekleri düşünün; Türkçedeki “sofra” gibi. <b>밥상을 차리다 / 치우다</b> (sofra kurmak / kaldırmak) ve 밥상 앞에 앉다 ile kullanılır.","엄마가 맛있는 **밥상**을 차려 주셨어요.","Annem bize lezzetli bir sofra hazırladı."],
["잡곡밥","karışık tahıllı pilav","잡곡 = karışık tahıllar (현미, 보리, 콩). 흰쌀밥'ın sağlıklı karşıtı olarak kullanılır.","요즘 건강 때문에 **잡곡밥**을 먹어요.","Bu aralar sağlığım için karışık tahıllı pilav yiyorum."],
["마음먹다","karar vermek, niyet etmek","Genellikle <b>-기로 마음먹다</b>. 마음먹은 대로 = niyet ettiğin gibi. 마음만 먹으면 = bir kafana koyarsan.","올해는 야식을 끊기로 **마음먹었어요**.","Bu yıl gece atıştırmalarını bırakmaya karar verdim."],
["시키다","(yemek) sipariş etmek; birine bir şey yaptırmak","주문하다'nın günlük dildeki karşılığı, özellikle paket servis için: <b>치킨을 시켜 먹다</b>. Ettirgen anlamı da var: 동생에게 청소를 시키다 (kardeşime temizlik yaptırmak).","피곤해서 저녁은 배달 음식을 **시켰어요**.","Yorgundum, akşam yemeği için paket servis söyledim."],
["차리다","(sofra) kurmak, (yemek) hazırlamak; (dükkân) açmak","<b>밥상/상을 차리다</b>, 가게를 차리다 (dükkân açmak), 정신을 차리다 (kendine gelmek, toparlanmak).","손님이 오셔서 저녁상을 **차렸어요**.","Misafirler geldi, akşam sofrasını kurdum."],
["그러게","değil mi ya; aynen","Samimi onaylama (kibar hâli: 그러게요). Ayrıca 그러게 내가 뭐랬어 = ben sana demiştim.","A: 요즘 너무 덥지? B: **그러게**. 입맛이 없어.","A: Bu aralar çok sıcak, değil mi? B: Aynen. Hiç iştahım yok."],
["마침","tam o sırada; tam zamanında","Denk gelen bir tesadüf için. 마치 (sanki) ve 마침내 (sonunda) ile karıştırmayın. 마침 잘됐다 = tam zamanında oldu.","배가 고팠는데 **마침** 친구가 떡을 가져왔어요.","Acıkmıştım, tam o sırada bir arkadaşım pirinç keki getirdi."]],
x:[["데우다","ısıtmak (pişmiş yemeği veya sıvıyı)","Tekrar ısıtmak için: 국/우유를 데우다, 전자레인지에 데우다. 끓이다 = kaynatmak. 데다 = (sıcakla) yanmak (farklı bir kelime).","남은 국을 **데워서** 먹었어요.","Artan çorbayı ısıtıp yedim."],
["데치다","haşlamak (kısa süre)","Kaynar suya kısaca daldırıp çıkarmak: <b>시금치/브로콜리를 살짝 데치다</b>.","시금치를 끓는 물에 살짝 **데쳤어요**.","Ispanağı kaynar suda hafifçe haşladım."],
["손쉽다","kolay, zahmetsiz","Çoğunlukla 손쉽게 ya da 손쉬운 şeklinde: “kolayca, zahmetsiz”. ㅂ düzensiz: 손쉬워요.","집에서 **손쉽게** 만들 수 있는 건강 요리예요.","Evde kolayca yapabileceğiniz sağlıklı bir yemek."],
["식히다¹","soğutmak","식다'nın ettirgen hâli (soğumak → soğutmak). 뜨거운 국을 식히다. Deyim: <b>머리를 식히다</b> = kafa dinlemek.","국이 너무 뜨거워서 좀 **식혀서** 먹었어요.","Çorba çok sıcaktı, biraz soğutup öyle yedim."],
["손이 가다","(1) çok emek istemek; (2) (yiyeceğe) elini durduramamak","(1) <b>손이 많이 가는 음식</b> = çok emek isteyen yemek. (2) 자꾸 손이 가요 = elimi durduramıyorum.","김밥은 **손이 많이 가서** 자주 못 만들어요.","Gimbap çok emek istiyor, o yüzden sık yapamıyorum."]]},
{n:2,t:"건강한 생활 습관",g:[
{f:"도 -이지만",en:"X de önemli ama (asıl) Y",
core:"Kalıp <b>N도 N이지만</b> şeklindedir; aynı isim tekrarlanır. Bir etkeni kabul edip daha önemli bulduğunuz noktaya geçersiniz. Türkçedeki “fiyatı da fiyat ama…” ya da “para da para ama…” söyleyişine çok benzer.",
forms:[["İsim, 받침 var","음식도 음식이지만 · 돈도 돈이지만"],["İsim, 받침 yok","운동도 운동이지만 · 나이도 나이지만 (konuşmada ünlüden sonra 이 düşer)"]],
rules:["Aynı isim iki kez geçer: <b>맛도 맛이지만</b>, asla 맛도 가격이지만 denmez.",
"İkinci cümle daha büyük ya da daha önemli noktayı söyler; çoğunlukla 더, 무엇보다, 그보다 ile.",
"Konuşma sınavlarında ve kompozisyonlarda dengeli görüş bildirmek için kullanışlıdır."],
ex:[["**운동도 운동이지만** 잠을 충분히 자는 게 더 중요해요.","Spor da önemli ama yeterince uyumak daha önemli."],
["이 식당은 **맛도 맛이지만** 분위기가 정말 좋아요.","Bu restoranın yemekleri de güzel ama asıl ortamı harika."],
["**돈도 돈이지만** 건강을 해치면 아무 소용이 없어요.","Para da para ama sağlığını bozarsan hiçbir anlamı kalmaz."]]},
{f:"-지요",en:"(tabii ki) X, bilirsin — bir şeyi açık ya da tecrübeyle bilinen bir şey olarak söylemek",
core:"Konuşan, bir şeyi çoğunlukla kendi tecrübesinden iyi bildiği bir gerçek ya da dinleyenin kabul etmesi gereken sağduyu olarak sunar: “Tabii ki zaman alır”, “Ben de zorlanmıştım, bilirsin.” Kitabınızda bir 선배 bunu bir 후배'yı rahatlatmak için kullanır, ardından tavsiye verir. Ton kendinden emin ama sıcaktır.",
forms:[["Fiil","걸리지요 · 고생했지요 · 없지요"],["Sıfat","힘들지요 · 중요하지요 · 외로웠지요"],["İsim","당연하지요 · 처음이지요 · 문제지요"],["Samimi (반말)","걸리지 · 했지 · 중요하지"]],
rules:["받침 olsun olmasın gövde + 지요. Geçmiş zaman: <b>-았/었지요</b>. Konuşmadaki kısa hâli: <b>-죠</b>. Samimi: <b>-지</b>.",
"Alçalan tonlamayla söylenir. Yükselen tonlamayla -지요? onay ister (“değil mi?”); bu farklı bir kullanımdır.",
"Bu ünitedeki tipik akış: <b>tecrübe ya da genel gerçek + -지요</b>, ardından tavsiye: 시간이 걸리지. 녹음해서 들어 봐.",
"Sıklıkla 당연히, 원래, 누구나, 처음에는, 나도 ile birlikte gelir; hepsi “bu iş böyledir” hissini güçlendirir.",
"Karşılaştırın: -잖아요 da ortak bilgiyi sunar ama “bunu zaten biliyorsun” anlamını taşır. -지요 ise sadece açık bir şey olarak söyler."],
ex:[["강의를 제대로 알아듣기까지는 시간이 **걸리지**. 녹음해서 여러 번 들어 봐.","Dersleri tam anlayabilmek zaman alır tabii. Kaydedip birkaç kez dinle."],
["나도 처음에는 보고서 쓰느라 고생을 많이 **했지**. 다양한 글을 많이 읽고 써 봐.","Ben de başta rapor yazarken çok zorlanmıştım. Farklı türde bol bol okuyup yaz."],
["아르바이트와 공부를 둘 다 잘할 수는 **없지요**. 하나를 선택해서 열심히 하는 게 좋아요.","Tabii ki hem yarı zamanlı işi hem de dersleri aynı anda iyi götüremezsin. Birini seçip ona odaklanmak daha iyi."]]}],
v:[["방해","engel, rahatsızlık","<b>방해(가) 되다</b>, 방해하다, 수면 방해. N에 방해가 되다 = N'ye engel olmak.","자기 전에 휴대폰을 보면 숙면에 **방해**가 돼요.","Yatmadan önce telefona bakmak derin uykuyu engelliyor."],
["숙면","derin, deliksiz uyku","Resmî. <b>숙면을 취하다</b> = deliksiz uyumak. Sağlık yazılarında sık geçer.","따뜻한 우유는 **숙면**에 도움이 돼요.","Ilık süt deliksiz uyumaya yardımcı olur."],
["놓다¹","koymak, bırakmak; (bir durumda) bırakmak","Temel anlamı: koymak. Ayrıca yardımcı fiil <b>-아/어 놓다</b> (켜 놓다 = açık bırakmak). 마음을 놓다 = içi rahatlamak.","휴대폰을 침대에서 먼 곳에 **놓고** 자요.","Uyurken telefonumu yataktan uzak bir yere koyuyorum."],
["들이다¹","(alışkanlık) edinmek","Bu anlamı: <b>습관을 들이다</b> = alışkanlık edinmek. (5과'daki 들이다² = para/zaman harcamak.)","아이에게 일찍 자는 습관을 **들이는** 게 중요해요.","Çocuklara erken yatma alışkanlığı kazandırmak önemlidir."],
["잠들다","uykuya dalmak","잠이 들다 ile aynı. 잠들기 전에 = uykuya dalmadan önce. 자다 uyuma hâlidir; 잠들다 ise uykuya geçiş anıdır.","책을 읽다가 **잠들었어요**.","Kitap okurken uyuyakaldım."],
["아무래도","galiba, (her şey düşünülünce) sonuçta","Konuşanın düşündükten sonra vardığı sonuç: <b>아무래도 -는 것 같다</b>. Ayrıca “nereden bakarsan bak” anlamı.","**아무래도** 커피 때문에 잠을 못 자는 것 같아요.","Galiba kahve yüzünden uyuyamıyorum."]],
x:[["바르다","düzgün, doğru","Sıfat: <b>바른 자세</b>, 바른 생활 습관. 르 düzensiz: 발라요. (Krem sürmek anlamındaki 바르다 farklı bir fiildir.)","**바른** 자세로 앉으면 허리가 덜 아파요.","Düzgün oturursanız beliniz daha az ağrır."],
["이롭다","faydalı, yararlı","Resmî. <b>몸에 이롭다</b>. ㅂ düzensiz: 이로워요. Zıt anlamlısı 해롭다.","녹차는 몸에 **이로운** 성분이 많아요.","Yeşil çayda vücuda faydalı birçok madde var."],
["해롭다","zararlı","<b>N에 해롭다</b>: 건강에 해롭다. ㅂ düzensiz: 해로워요.","담배는 건강에 **해로워요**.","Sigara sağlığa zararlıdır."],
["해치다","zarar vermek, bozmak","Geçişli fiil, nesne alır: <b>건강을 해치다</b>. 해롭다 ise “zararlı” anlamındaki sıfattır.","무리한 다이어트는 건강을 **해칠** 수 있어요.","Aşırı diyet sağlığa zarar verebilir."],
["몸에 배다","alışkanlık hâline gelmek, işlemek","배다 = sinmek, işlemek (냄새가 옷에 배다 = koku elbiseye sinmek). <b>습관이 몸에 배다</b>.","일찍 일어나는 습관이 **몸에 배어서** 주말에도 6시에 깨요.","Erken kalkmak öyle alışkanlık oldu ki hafta sonları bile 6'da uyanıyorum."]]}]});

GUIDE.tr.push({n:2,t:"한국어 학습",en:"Korece Öğrenimi",units:[
{n:1,t:"한국어 학습 목적",g:[
{f:"어찌나 -는지",en:"o kadar X ki Y",
core:"Bir şeyin ne kadar aşırı olduğunu vurgular, ardından sonucu verir. <b>어찌나</b> (= 얼마나, daha vurgulu) şiddeti artırır, -는지 da sonuç cümlesini hazırlar. Türkçedeki “öyle … ki” yapısına denk gelir.",
forms:[["Fiil","어찌나 먹는지 · 어찌나 웃었는지"],["Sıfat","어찌나 비싼지 · 어찌나 추웠는지"],["İsim","어찌나 미인인지"]],
rules:["Fiilde şimdiki zaman -는지, sıfatta şimdiki zaman -(으)ㄴ지, geçmiş zaman -았/었는지.",
"İkinci cümle sonucu bildirir; çoğunlukla -았/었어요 ya da -(으)ㄹ 정도였어요 ile.",
"Genellikle konuşanın yaşadığı ya da gördüğü şeyler için kullanılır. Konuşma diline ait, duygu yüklü bir ifadedir.",
"얼마나 -는지 da aynı anlamdadır ve 모르다 ile de kullanılır: 얼마나 맛있는지 몰라요 (ne kadar lezzetli, bilemezsin)."],
ex:[["한국 드라마가 **어찌나 재미있는지** 밤새 봤어요.","Kore dizisi o kadar eğlenceliydi ki bütün gece izledim."],
["그 가수를 **어찌나 좋아했는지** 혼자 한국어를 공부하기 시작했어요.","O şarkıcıyı o kadar sevdim ki kendi kendime Korece çalışmaya başladım."],
["시험이 **어찌나 어려웠는지** 반도 못 풀었어요.","Sınav o kadar zordu ki yarısını bile çözemedim."]]},
{f:"-도록¹",en:"-sin diye; -mesi için",
core:"Amaç ya da hedef bildirir. Ana cümledeki eylem, -도록 cümlesindeki şey gerçekleşsin diye yapılır. -(으)려고 veya -기 위해 ile karşılaştırıldığında, çoğunlukla başkası için bir sonucu ya da durumu sağlamaya odaklanır. Türkçedeki “duysunlar diye”, “unutmamak için” yapısına benzer.",
forms:[["Fiil / sıfat gövdesi","들리도록 · 잊지 않도록 · 늦지 않도록 · 건강하도록"]],
rules:["받침 olsun olmasın gövde + 도록.",
"Özneler çoğunlukla farklıdır: <b>학생들이 이해하도록</b> 선생님이 천천히 설명했어요.",
"Olumsuzla çok sık kullanılır: <b>-지 않도록</b> = -memek için.",
"도록 cümlesinde zaman eki olmaz.",
"Talimatlarda da kullanılır: 내일까지 제출하<b>도록</b> 하세요 (resmî emir).",
"“-ecek kadar, -ecek derecede” anlamında derece bildiren -도록² (7과) ile farklıdır."],
ex:[["뒤에 앉은 사람도 잘 **들리도록** 크게 말해 주세요.","Arkada oturanlar da iyi duysun diye yüksek sesle konuşun lütfen."],
["단어를 **잊어버리지 않도록** 매일 복습해요.","Kelimeleri unutmamak için her gün tekrar ediyorum."],
["한국 기업에 **취직할 수 있도록** 비즈니스 한국어를 배우고 있어요.","Bir Kore şirketinde işe girebilmek için iş Korecesi öğreniyorum."]]}],
v:[["계기","vesile, (bir şeye yol açan) etken","<b>N이/가 계기가 되다</b>, <b>N을/를 계기로</b>. Klasik mülakat sorusu: 무슨 계기로 한국어를 배우게 됐어요?","한국 여행이 **계기**가 되어 한국어를 배우게 됐어요.","Kore gezisi vesilesiyle Korece öğrenmeye başladım."],
["기업","şirket, kuruluş","회사'dan daha resmî ya da ekonomik bir kelime. 대기업 (büyük şirket), 중소기업 (KOBİ), 기업 문화.","외국 **기업**에서 한국어를 할 수 있는 사람을 찾고 있어요.","Yabancı şirketler Korece konuşabilen kişiler arıyor."],
["관련되다","ilgili olmak, alakalı olmak","<b>N와/과 관련된 N</b>, N와 관련이 있다. 관련 = ilgili (관련 자료 = ilgili belgeler).","IT와 **관련된** 일을 하고 싶어요.","Bilişimle ilgili bir işte çalışmak istiyorum."],
["진출하다","(bir pazara ya da alana) girmek, açılmak","<b>해외/시장에 진출하다</b>. Sporda da: 결승에 진출하다 = finale yükselmek.","그 회사는 작년에 한국 시장에 **진출했어요**.","O şirket geçen yıl Kore pazarına girdi."],
["우연히","tesadüfen","<b>우연히 만나다 / 알게 되다 / 보다</b>. 우연 = tesadüf.","유튜브에서 **우연히** 한국 노래를 듣게 됐어요.","YouTube'da tesadüfen bir Kore şarkısı dinledim."]],
x:[["개발","geliştirme (ürün, teknoloji, beceri)","개발하다, 앱 개발, 능력 개발. Not: kişisel gelişim doğru olarak <b>자기계발</b> yazılır (계발 = yeteneği geliştirme), 자기개발 değil.","저는 게임 **개발**에 관심이 있어요.","Oyun geliştirmeye ilgim var."],
["능력","yetenek, beceri","<b>능력이 있다 / 뛰어나다</b>, 능력을 키우다/기르다. 한국어 능력 시험 = TOPIK.","외국어 **능력**이 있으면 취업에 유리해요.","Yabancı dil bilmek iş ararken avantaj sağlar."],
["동기","güdü, motivasyon","학습 동기, <b>동기를 부여하다</b> (motive etmek). Eş sesli: 동기 = aynı dönemden arkadaş (입사 동기 = aynı dönem işe girenler).","한국어를 공부하는 **동기**가 뭐예요?","Korece çalışma motivasyonun ne?"],
["의사소통","iletişim","의사 = niyet, düşünce (doktor değil). <b>의사소통이 되다 / 안 되다</b>, 의사소통 능력.","이제는 한국 사람과 **의사소통**하는 데 문제가 없어요.","Artık Korelilerle iletişim kurmakta hiç zorlanmıyorum."],
["호기심","merak","<b>호기심이 많다</b>, 호기심을 느끼다/갖다, 호기심에 (meraktan).","**호기심**에 한글을 배워 봤는데 재미있었어요.","Meraktan Hangıl öğrenmeyi denedim, eğlenceliydi."],
["흥미","ilgi","<b>흥미가 있다 / 생기다</b>, 흥미를 느끼다/잃다. 흥미롭다 = ilginç. 관심'den biraz daha resmî.","역사에 **흥미**가 생겨서 한국 역사 책을 읽고 있어요.","Tarihe ilgi duymaya başladım, Kore tarihi üzerine bir kitap okuyorum."]]},
{n:2,t:"효과적인 학습 방법",g:[
{f:"-을 게 아니라",en:"X yapacağına Y yap; X'mek yerine Y",
core:"Bir yolu doğru yaklaşım olmadığı gerekçesiyle reddeder ve daha iyisini önerir. Çoğunlukla tavsiyede kullanılır: “Sadece X'me, onun yerine Y.” (게 = 것이) Türkçedeki “-eceğine” yapısına benzer.",
forms:[["Fiil, 받침 yok","볼 게 아니라 · 외울 게 아니라 (ㄹ ile biten gövde)"],["Fiil, 받침 var","읽을 게 아니라 · 앉아 있을 게 아니라"]],
rules:["Yalnızca fiillerle kullanılır. İlk cümlede zaman eki olmaz.",
"İkinci cümle genellikle tavsiye, emir ya da öneridir: -(으)세요, -는 게 좋겠어요, -아/어야 해요, -(으)ㅂ시다.",
"Reddedilen yolun düşünülmeden yapıldığını göstermek için ilk cümlede sık sık 그냥 veya 무조건 kullanılır: <b>그냥 외울 게 아니라</b>.",
"Yalnızca isimlerle kullanılan N이/가 아니라 (N değil M) ile karşılaştırın."],
ex:[["단어를 그냥 **외울 게 아니라** 문장으로 만들어 보세요.","Kelimeleri sadece ezberleyeceğinize onlarla cümle kurmayı deneyin."],
["번역기에 **의존할 게 아니라** 사전을 찾아보는 게 좋아요.","Çeviri programına güveneceğinize sözlüğe bakmanız daha iyi."],
["혼자 **고민할 게 아니라** 선생님께 여쭤봐요.","Tek başına kafa yoracağına öğretmene sor."]]},
{f:"-기에는",en:"X için; X'mek için (uygunluk değerlendirmesi)",
core:"Bir değerlendirme ölçütü verir: “X amacı için (fazla / yetersiz / iyi).” Ardından genellikle 좋다, 어렵다, 부족하다, 이르다, 너무 -다 gibi bir değerlendirme gelir.",
forms:[["Fiil","혼자 먹기에는 · 공부하기에는 · 포기하기에는"]],
rules:["Fiil gövdesi + 기에는. Konuşmada <b>-기엔</b> şeklinde kısalabilir.",
"Ana cümle bir değerlendirmedir, genellikle sıfat: 많다, 비싸다, 이르다, 아깝다, 적당하다.",
"Çoğunlukla “uygun değil” anlamını ima eder: 초보자가 보기에는 어려워요.",
"Eylemi yapan kişi için N이/가 -기에는 de kullanılır: 아이가 읽기에는 어려운 책 (bir çocuğun okuması için zor bir kitap)."],
ex:[["이 교재는 초급 학생이 **공부하기에는** 좀 어려워요.","Bu ders kitabı başlangıç seviyesindeki öğrencilerin çalışması için biraz zor."],
["포기하**기에는** 아직 일러요.","Pes etmek için henüz çok erken."],
["드라마는 듣기 연습을 **하기에는** 좋지만 문법을 배우**기에는** 부족해요.","Diziler dinleme pratiği yapmak için iyi ama dil bilgisi öğrenmek için yetersiz."]]}],
v:[["매체","araç, medya","대중 매체 (kitle iletişim araçları), 다양한 매체를 통해, 영상 매체.","요즘은 다양한 **매체**를 통해 한국어를 배울 수 있어요.","Bugünlerde Koreceyi pek çok farklı araçla öğrenebilirsiniz."],
["수준","seviye, düzey","<b>수준이 높다 / 낮다</b>, N에 수준이 맞다, 생활 수준 (yaşam standardı). 자기 수준에 맞는 책 = seviyene uygun kitap.","제 **수준**에 맞는 책을 고르는 게 어려워요.","Seviyeme uygun kitap seçmek zor."],
["효과적","etkili","-적 ekli isim: 효과적이다, 효과적인 방법, 효과적으로. 효과 = etki. 효율적 (verimli) ile karşılaştırın, 10과.","소리 내서 읽는 것이 발음 연습에 **효과적**이에요.","Sesli okumak telaffuz pratiği için etkilidir."],
["의존하다","bağımlı olmak, -e dayanmak","<b>N에 의존하다</b>. Aşırı bağımlılık anlamında hafif olumsuz bir çağrışımı vardır.","사전에만 **의존하지** 말고 문맥으로 뜻을 추측해 보세요.","Sadece sözlüğe güvenmeyin. Anlamı bağlamdan tahmin etmeye çalışın."],
["상당히","oldukça, epey","Biraz resmî “oldukça, epey”. 아주 veya 너무'dan daha ölçülüdür.","한국어 실력이 **상당히** 늘었네요.","Koreceniz epey ilerlemiş."],
["서서히","yavaş yavaş, giderek","Yavaş ve istikrarlı değişim: <b>서서히 늘다 / 좋아지다 / 익숙해지다</b>. 점점 daha nötrdür.","처음에는 힘들었지만 **서서히** 익숙해졌어요.","Başta zordu ama yavaş yavaş alıştım."]],
x:[["암기하다","ezberlemek","Resmî ya da akademik. Günlük dildeki karşılığı: 외우다. 암기력 = ezber gücü.","시험 전에 단어를 열심히 **암기했어요**.","Sınavdan önce kelimeleri sıkı çalışarak ezberledim."],
["유창하다","akıcı","Çoğunlukla dil ve konuşma için: <b>유창하게 말하다</b>. 유창한 한국어.","저도 언젠가 한국어를 **유창하게** 하고 싶어요.","Ben de bir gün Koreceyi akıcı konuşmak istiyorum."],
["완벽하다","mükemmel, kusursuz","완벽하게, 완벽주의자 (mükemmeliyetçi).","**완벽하게** 말하려고 하지 말고 자신 있게 말해 보세요.","Kusursuz konuşmaya çalışmayın. Sadece kendinize güvenerek konuşun."],
["향상되다","gelişmek, ilerlemek (seviye, yetenek)","Geçişsiz: <b>실력이 향상되다</b>. Geçişli: 실력을 향상시키다. 늘다'dan daha resmî.","매일 일기를 쓰니까 쓰기 실력이 **향상됐어요**.","Her gün günlük tutunca yazma becerim gelişti."],
["꾸준히","istikrarlı bir şekilde, düzenli olarak","Zamana yayılan düzenli çaba: <b>꾸준히 연습하다 / 운동하다</b>.","**꾸준히** 공부하면 누구나 실력이 늘어요.","Düzenli çalışan herkes ilerler."]]}]});
GUIDE.tr.push({n:3,t:"성격과 환경",en:"Kişilik ve çevre",units:[
{n:1,t:"성격",g:[
{f:"-었던 것 같다",en:"sanırım …-dı / …-mış gibi (geçmişi hatırlama)",
core:"Geçmiş hakkında yumuşak, kesin olmayan bir ifade. Bir şeyi hatırlıyorsunuz ama %100 emin değilsiniz ya da alçakgönüllü veya dolaylı konuşuyorsunuz. -었던 kısmı tamamlanmış bir geçmiş durumu ya da artık sürmeyen bir geçmişi gösterir.",
forms:[["Fiil","갔던 것 같다 · 먹었던 것 같다"],["Sıfat","조용했던 것 같다 · 작았던 것 같다"],["İsim","학생이었던 것 같다 · 친구였던 것 같다"]],
rules:["Fiil, sıfat ve 이다 ile kullanılır.",
"Karşılaştırın: <b>-(으)ㄴ 것 같다</b> (fiil geçmiş: 간 것 같다 = sanırım gitti) yakın bir olay hakkında tahmindir. <b>-었던 것 같다</b> ise bitmiş bir şeye geriye dönüp bakmak ya da değişmiş bir geçmiş durumu hatırlamak gibidir.",
"Sıfatlarla doğal geçmiş tahmini <b>-었던 것 같다</b> ile yapılır: 어렸을 때 조용했던 것 같아요.",
"Eskiden kişiliğinizin nasıl olduğunu anlatmak için çok uygundur."],
ex:[["어렸을 때는 정말 **내성적이었던 것 같아요**.","Sanırım çocukken çok içe dönüktüm."],
["그 사람을 예전에 어디서 **만났던 것 같은데** 기억이 안 나요.","Sanırım o kişiyle daha önce bir yerde tanışmıştım ama hatırlayamıyorum."],
["고등학교 때는 지금보다 더 **활발했던 것 같아요**.","Sanırım lisedeyken şimdikinden daha hareketliydim."]]},
{f:"-더니¹",en:"(X olduğunu gördüm,) sonra / ama şimdi Y",
core:"Konuşanın geçmişte gözlemlediği bir şeye dayanır; ardından bir değişim, karşıtlık ya da sonuç gelir. İki ana kullanım: (1) <b>karşıtlık veya değişim</b>: 어제는 춥더니 오늘은 따뜻하네요. (2) <b>neden ve sonuç</b>: 열심히 공부하더니 합격했어요.",
forms:[["Fiil / sıfat gövdesi","춥더니 · 공부하더니 · 조용하더니"],["İsim","학생이더니"]],
rules:["Gövde + 더니; 받침 olup olmaması fark etmez.",
"Genellikle konuşanın kendisi hakkında değil, <b>başka biri</b> ya da hava durumu ve nesneler hakkındadır. Bunu doğrudan gözlemlemişsinizdir.",
"İki cümleciğin öznesi normalde aynıdır.",
"Konuşanın kendi eylemi için <b>-었더니</b> (X yaptım ve Y olduğunu gördüm) kullanılır; bu farklı bir yapıdır: 약을 먹었더니 괜찮아졌어요.",
"Bu kullanımda 더니'den önce geçmiş zaman gelmez: 추웠더니 değil, 춥더니 (öbürü 었더니 yapısına geçer)."],
ex:[["민수 씨는 예전에는 **덜렁거리더니** 요즘은 정말 꼼꼼해졌어요.","Minsu eskiden çok dalgındı ama bu aralar gerçekten titiz oldu."],
["동생이 아침부터 **울먹거리더니** 결국 울음을 터뜨렸어요.","Küçük kardeşim sabahtan beri ağlamaklıydı, sonunda hüngür hüngür ağlamaya başladı."],
["어제는 날씨가 **맑더니** 오늘은 비가 오네요.","Dün hava açıktı ama bugün yağmur yağıyor."]]}],
v:[["무표정","ifadesiz yüz, ifadesizlik","<b>무표정하다</b>, 무표정한 얼굴, 무표정으로 (ifadesiz bir yüzle). 무- = -sız/-siz.","그 사람은 항상 **무표정**이라서 기분을 알 수가 없어요.","Yüzü hep ifadesiz olduğu için ruh hâlini anlamak mümkün değil."],
["예전","geçmiş, eski zamanlar","<b>예전에</b> (eskiden), 예전부터 (uzun zamandır), <b>예전 같지 않다</b> (eskisi gibi değil).","**예전**에는 수줍음이 많았는데 지금은 아니에요.","Eskiden çok utangaçtım ama artık değilim."],
["꼼꼼하다","titiz, dikkatli","Olumlu: ayrıntılara özen gösteren. 꼼꼼하게 확인하다. Karşıtı: 덜렁거리다.","제 친구는 **꼼꼼해서** 실수를 거의 안 해요.","Arkadaşım titiz olduğu için neredeyse hiç hata yapmaz."],
["내성적이다","içe dönük","Karşıtı: 외향적이다. Tarafsız bir tanımdır, olumsuz değildir.","저는 **내성적**이라서 처음 만난 사람과 말하는 게 어려워요.","İçe dönük olduğum için yeni tanıştığım insanlarla konuşmak bana zor geliyor."],
["덜렁거리다","dikkatsiz / dalgın olmak","Fiildir (sıfat değil): 그는 덜렁거려요. 덜렁대다 ile aynı. Böyle birine 덜렁이 denir.","저는 **덜렁거려서** 우산을 자주 잃어버려요.","O kadar dalgınım ki şemsiyemi sık sık kaybediyorum."],
["울먹거리다","ağlamaklı olmak","Sesi titreyerek neredeyse ağlamak. 울먹이다 ile aynı.","아이가 엄마를 찾으면서 **울먹거렸어요**.","Çocuk annesini ararken ağlamaklı oldu."],
["활발하다","hareketli, canlı, dışa dönük","Kişilik için. Etkinlik için de: 활발한 토론, 활발하게 활동하다.","언니는 성격이 **활발해서** 친구가 많아요.","Ablam dışa dönük olduğu için çok arkadaşı var."]],
x:[["느긋하다","rahat, aceleci olmayan, sakin","Olumlu veya tarafsız: telaşsız. Fazla yavaş anlamına gelirse olumsuz olabilir.","그는 성격이 **느긋해서** 급한 일이 있어도 화를 안 내요.","O kadar rahat biri ki acil bir iş olsa bile sinirlenmiyor."],
["소극적이다","pasif, çekingen","Katılmaya ya da söz almaya çekinen. Karşıtı: 적극적이다.","수업 시간에 너무 **소극적**이면 실력이 잘 안 늘어요.","Derste fazla çekingen olursan pek ilerleme kaydedemezsin."],
["수동적이다","edilgen (yalnızca söylenince harekete geçen)","Talimat bekler ya da kendisi harekete geçmek yerine tepki verir. Karşıtı: 능동적이다. 소극적 çekingenlikle, 수동적 inisiyatif eksikliğiyle ilgilidir.","시키는 일만 하는 **수동적**인 태도는 좋지 않아요.","Yalnızca söyleneni yapan edilgen bir tutum iyi değildir."],
["적극적이다","etkin, girişken, istekli","<b>적극적으로 참여하다</b>. Kore'de iş yerlerinde ve okullarda çok değer görür.","그 학생은 모든 활동에 **적극적**으로 참여해요.","O öğrenci her etkinliğe etkin biçimde katılıyor."],
["주도적이다","öncü, inisiyatif alan","Yönlendiren veya başlatan: 주도적으로 이끌다. 주도하다 = önderlik etmek.","팀 프로젝트에서 **주도적**인 역할을 맡았어요.","Takım projesinde öncü bir rol üstlendim."]]},
{n:2,t:"환경의 영향",g:[
{f:"-는다고 해서",en:"sırf X diye (Y anlamına gelmez)",
core:"Varsayılan bir bağlantıyı reddeder: X'in doğru olması otomatik olarak Y anlamına gelmez. Genellikle olumsuz ya da retorik bir cümlecik izler: 아니다, -는 것은 아니다, 다 -는 건 아니다. Türkçedeki “…-dı diye … değil” yapısına çok benzer.",
forms:[["Fiil","간다고 해서 · 먹는다고 해서 · 했다고 해서"],["Sıfat","비싸다고 해서 · 작다고 해서"],["İsim","학생이라고 해서 · 부자라고 해서"]],
rules:["Dolaylı anlatımdaki -ㄴ/는다고, -다고, -(이)라고 biçimlerini kullanır, bu yüzden geçmiş ve gelecek zaman mümkündür: <b>잘했다고 해서</b>.",
"İkinci cümlecik beklenen sonucu reddeder: <b>-는 것은 아니다</b>, 다 -지는 않다, -(으)ㄹ 수는 없다.",
"Sık sık 다 ya da 꼭 ile: 형제라고 해서 성격이 <b>다</b> 같은 건 아니에요.",
"Konuşmada <b>-는다고</b> şeklinde kısaltılabilir."],
ex:[["형제**라고 해서** 성격이 다 비슷한 건 아니에요.","Kardeşler diye kişiliklerinin hepsi birbirine benzeyecek değil."],
["조용**하다고 해서** 소심한 사람은 아니에요.","Sessiz diye biri ürkek sayılmaz."],
["부모님이 이기적이**라고 해서** 아이도 이기적으로 자라는 건 아니지요.","Anne baba bencil diye çocuk da bencil büyüyecek değil ya."]]},
{f:"처럼",en:"gibi, -ca/-ce (karşılaştırma)",
core:"İsme eklenen edat: “N gibi, N'nin yaptığı şekilde.” Tarz veya derece bakımından benzerliği anlatır.",
forms:[["İsim","엄마처럼 · 그림처럼 · 바보처럼"],["Sıfat görevinde","N 같은 N (아빠 같은 사람). 처럼 fiili, 같은 ise ismi niteler."]],
rules:["<b>N처럼 + fiil/sıfat</b>: 아빠처럼 키가 커요.",
"Karşılaştırın: <b>N 같이</b> (aynı anlam, biraz daha gündelik) ve <b>N 같은 N</b> (isimden önce).",
"Yaygın benzetmeler: 그림처럼 아름답다, 꿈처럼, 거짓말처럼, 쥐 죽은 듯이 (bkz. -는 듯이, 10과).",
"Başka eklerden sonra gelebilir: 예전<b>처럼</b>, 지금<b>처럼</b>, 말한 것<b>처럼</b>."],
ex:[["저는 아빠**처럼** 성격이 느긋한 편이에요.","Babam gibi ben de rahat biriyimdir."],
["예전**처럼** 친구들과 자주 만나지 못해요.","Arkadaşlarımla eskisi kadar sık görüşemiyorum."],
["언니**처럼** 다정한 사람이 되고 싶어요.","Ablam gibi sıcak kalpli biri olmak istiyorum."]]}],
v:[["불평","şikâyet, söylenme","<b>불평하다</b>, 불평을 늘어놓다 (şikâyet üstüne şikâyet etmek). 불평 yüksek sesle şikâyet etmektir; 불만 ise memnuniyetsizlik duygusudur.","그는 항상 회사에 대해 **불평**만 해요.","Sürekli şirketinden şikâyet edip duruyor."],
["영향","etki","<b>N에게 영향을 주다 / 미치다 / 받다</b>. 영향력 = nüfuz, etki gücü (10과).","저는 엄마에게 많은 **영향**을 받았어요.","Annemden çok etkilendim."],
["이기적","bencil","-적 ismi: 이기적이다, 이기적인 사람. Karşıtı: 이타적 (özgeci).","**이기적**인 행동은 주변 사람을 힘들게 해요.","Bencil davranışlar çevredeki insanları zor durumda bırakır."],
["정","şefkat, bağlılık (Korece 정)","Zamanla oluşan sıcak bir bağ; Türkçede tam karşılığı yok, “gönül bağı”na yakın. <b>정이 많다</b> (sıcak kalpli), <b>정이 들다</b> (bağlanmak, ısınmak), 정을 주다.","이 동네에 오래 살아서 **정**이 많이 들었어요.","Bu mahallede o kadar uzun yaşadım ki ona çok bağlandım."],
["평생","ömür, ömür boyu","<b>평생 (동안)</b>, 평생 잊지 못하다. Zarf olarak da: 평생 함께하다.","어렸을 때 배운 습관은 **평생** 가요.","Çocukken edinilen alışkanlıklar ömür boyu sürer."],
["소심하다","ürkek, yüreksiz","Aşırı temkinli ve küçük şeylerden kolayca incinen. Hafif olumsuz. Karşıtı: 대범하다.","저는 **소심해서** 작은 일에도 걱정을 많이 해요.","Ürkek biri olduğum için küçük şeyler için bile çok endişeleniyorum."],
["타고나다","doğuştan sahip olmak","<b>타고난 성격 / 재능</b>, 성격은 타고나는 걸까요? Doğa mı yetiştirme mi konusunun anahtar kelimesi.","그는 음악적 재능을 **타고났어요**.","Müzik yeteneği doğuştan."]],
x:[["긍정적이다","olumlu, pozitif","긍정적으로 생각하다. Karşıtı: 부정적이다.","**긍정적**인 사람과 있으면 기분이 좋아져요.","Pozitif insanlarla birlikte olunca keyfim yerine geliyor."],
["냉정하다","soğuk; soğukkanlı","İki yüzü var: olumsuz (soğuk kalpli: 냉정한 사람) ya da tarafsız-olumlu (sakin ve nesnel: 냉정하게 판단하다).","화가 나도 **냉정하게** 생각하려고 해요.","Sinirlensem bile soğukkanlı düşünmeye çalışırım."],
["다정하다","sevecen, sıcak, nazik","Davranış ve sözlerde gösterilen sıcaklık. 다정한 말투.","우리 할머니는 언제나 **다정하세요**.","Babaannem her zaman çok sevecendir."],
["대범하다","cesur, geniş yürekli","Küçük şeyleri dert etmeyen. Karşıtı: 소심하다.","그녀는 **대범해서** 실수해도 금방 털고 일어나요.","O kadar geniş yürekli ki hata yapsa bile hemen silkinip toparlanıyor."],
["모나다","köşeli, aksi (kişilik)","Kelimesi kelimesine “köşeleri olan.” <b>모난 성격</b> = huysuz, aksi. Atasözü: 모난 돌이 정 맞는다 (köşeli taş keskiyi yer; göze batan başını yakar).","**모난** 성격 때문에 친구와 자주 싸워요.","Aksi huyu yüzünden arkadaşlarıyla sık sık kavga ediyor."],
["못되다","kötü, huysuz, hain","<b>못된 버릇 / 사람</b>. Bitişik yazılır. (못 되다 = olamamak; farklı anlam.)","친구를 놀리는 건 **못된** 행동이에요.","Arkadaşlarınla dalga geçmek kötü bir davranış."],
["부정적이다","olumsuz, negatif","부정적인 영향, 부정적으로 생각하다.","**부정적**인 말은 아이에게 나쁜 영향을 줘요.","Olumsuz sözler çocukları kötü etkiler."],
["원만하다","uyumlu, geçimli; sorunsuz","Kişilik ve ilişkiler için. Ayrıca: 문제를 <b>원만하게 해결하다</b> (sorunu tatlıya bağlamak).","그는 성격이 **원만해서** 누구와도 잘 지내요.","Geçimli biri olduğu için herkesle iyi anlaşıyor."]]}]});

GUIDE.tr.push({n:4,t:"나의 진로",en:"Kariyer yolum",units:[
{n:1,t:"진로 고민",g:[
{f:"-고 보니까",en:"X'i yaptıktan sonra fark ettim / anlaşıldı ki",
core:"Bir eylem tamamlandıktan sonra konuşan yeni bir şey fark eder; çoğu zaman önceden bilmediği ya da beklenmedik bir şey. Odak, tek bir eylemi tamamladıktan sonraki keşiftir. Türkçedeki “…-ınca anladım ki” yapısına benzer.",
forms:[["Fiil","하고 보니까 · 듣고 보니까 · 졸업하고 보니까"],["İsim (이다)","알고 보니까 (= 알고 보니, “meğer”)"]],
rules:["Yalnızca fiillerle; -고'dan önce zaman eki gelmez.",
"<b>-다(가) 보니까</b> (1과) ile karşılaştırın: o, sürekli ya da tekrarlanan bir eylemin bir keşfe yol açmasıdır. -고 보니까 ise tek bir eylemi tamamlayıp ardından bir şey keşfetmektir.",
"Kısa biçim <b>-고 보니</b> yaygındır, özellikle <b>알고 보니</b> (meğer, anlaşıldı ki).",
"İkinci cümlecikte sık sık -더라고요, -네요, -었어요 bulunur."],
ex:[["대학교를 **졸업하고 보니까** 하고 싶은 일이 따로 있었어요.","Üniversiteyi bitirince asıl yapmak istediğim şeyin başka olduğunu fark ettim."],
["설명을 **듣고 보니까** 생각보다 간단한 문제였어요.","Açıklamayı dinleyince sorunun sandığımdan basit olduğu anlaşıldı."],
["**알고 보니** 그 사람이 박람회 담당자였어요.","Meğer o kişi fuarın sorumlusuymuş."]]},
{f:"-을 텐데",en:"(muhtemelen) X olduğuna göre, …",
core:"Konuşanın varsayımını ya da beklentisini ifade eder (텐데 = 터이다 + -ㄴ데) ve bunu bir tavsiye, endişe veya karşıt bir ifadenin arka planı olarak kullanır.",
forms:[["Fiil / sıfat, 받침 yok","바쁠 텐데 · 피곤할 텐데"],["Fiil / sıfat, 받침 var","좋을 텐데 · 많을 텐데"],["Geçmiş","했을 텐데 · 왔을 텐데"],["İsim","학생일 텐데 · 주말일 텐데"]],
rules:["Yaygın kalıp: <b>varsayım + tavsiye</b>: 피곤할 텐데 좀 쉬세요.",
"Ayrıca <b>varsayım + karşıtlık</b>: 많이 바쁠 텐데 와 줘서 고마워요.",
"Cümleyi <b>-(으)ㄹ 텐데요</b> ile bitirmek endişe ya da umut gösterir: 비가 오면 안 될 텐데요.",
"<b>-었을 텐데</b> = “-ırdı / -mış olurdu” (gerçekleşmemiş durum): 미리 알았으면 도와줬을 텐데."],
ex:[["취업 준비 때문에 **바쁠 텐데** 너무 무리하지 마세요.","İş arama hazırlığıyla meşgulsündür, kendini çok yorma."],
["혼자 결정하기 **어려울 텐데** 진로 상담을 받아 보세요.","Tek başına karar vermek muhtemelen zordur, kariyer danışmanlığı almayı dene."],
["미리 **알았으면** 박람회에 **갔을 텐데** 아쉬워요.","Önceden bilseydim fuara giderdim. Çok yazık."]]}],
v:[["담당자","sorumlu kişi, yetkili","담당하다 = -den sorumlu olmak. <b>담당자에게 문의하다</b> (yetkiliye danışmak).","자세한 내용은 **담당자**에게 문의하세요.","Ayrıntılar için lütfen yetkiliye başvurun."],
["박람회","fuar","취업 박람회 (kariyer fuarı), 유학 박람회, 박람회에 참가하다.","다음 주에 취업 **박람회**가 열려요.","Gelecek hafta bir kariyer fuarı düzenleniyor."],
["부담","yük, baskı","<b>부담이 되다 / 크다</b>, <b>부담을 주다 / 느끼다</b>. 부담스럽다 (10과). Maddi anlamda da: 비용 부담.","부모님께 경제적인 **부담**을 드리고 싶지 않아요.","Anne babama maddi yük olmak istemiyorum."],
["일거양득","bir taşla iki kuş","Dört heceli deyim (사자성어): 一擧兩得. Benzeri: 꿩 먹고 알 먹고.","운동도 하고 돈도 버니까 **일거양득**이에요.","Hem spor yapıyorum hem para kazanıyorum. Bir taşla iki kuş."],
["진로","kariyer yolu, gelecekteki yön","<b>진로를 정하다 / 고민하다</b>, 진로 상담 (kariyer danışmanlığı).","졸업이 다가오니까 **진로** 고민이 많아요.","Mezuniyet yaklaştığı için kariyer yolumu çok düşünüyorum."],
["시도하다","denemek, girişimde bulunmak","Yeni bir şey denemek: <b>새로운 것을 시도하다</b>. 해 보다'dan daha bilinçli.","두려워하지 말고 여러 가지 일을 **시도해** 보세요.","Korkma. Pek çok farklı şey dene."],
["게다가","üstelik, bir de","Genellikle aynı yönde ek bir nokta ekler (çoğu zaman iyi ya da kötü şeyleri üst üste sıralar).","월급이 많고 **게다가** 집에서도 가까워요.","Maaşı iyi, üstelik eve de yakın."]],
x:[["다재다능","çok yetenekli","多才多能. 다재다능하다, 다재다능한 사람.","그는 노래, 춤, 연기까지 하는 **다재다능**한 사람이에요.","Şarkı söyleyen, dans eden, hatta oyunculuk da yapan çok yetenekli biri."],
["상부상조","yardımlaşma","相扶相助. Geleneksel köy yaşamındaki gibi birbirine yardım etmek.","이웃끼리 **상부상조**하며 사는 게 좋아요.","Komşuların yardımlaşarak yaşaması iyidir."],
["우왕좌왕","şaşkınlıkla oraya buraya koşuşturma","右往左往. 우왕좌왕하다: ne yapacağını bilemeden koşuşturmak.","갑자기 정전이 돼서 사람들이 **우왕좌왕**했어요.","Elektrikler aniden kesilince insanlar şaşkınlıkla oraya buraya koşuştu."],
["우유부단","kararsız","優柔不斷. 우유부단하다, 우유부단한 성격.","저는 **우유부단**해서 메뉴 하나 고르는 데도 오래 걸려요.","O kadar kararsızım ki menüden tek bir şey seçmem bile çok uzun sürüyor."],
["유비무환","tedbirli olan felakete uğramaz","有備無患. Hazırlıklı olmayı öğütlerken kullanılır.","**유비무환**이라고 미리 자격증을 따 두세요.","Tedbir elden bırakılmaz derler; sertifikanı önceden al."],
["작심삼일","üç gün süren karar","作心三日. Başarısız kalan kararlar için.","운동하기로 했는데 또 **작심삼일**이 됐어요.","Spor yapmaya karar verdim ama yine üç gün sonra bıraktım."],
["전화위복","her işte bir hayır vardır","轉禍爲福. İyiliğe dönüşen bir talihsizlik.","회사에서 떨어진 게 오히려 **전화위복**이 됐어요.","O şirkete alınmamam meğer hayırlı olmuş."]]},
{n:2,t:"취업 박람회",g:[
{f:"-는지요?",en:"acaba … mı? / sorabilir miyim? (çok kibar soru)",
core:"Sanki yüksek sesle merak ediyormuş gibi yumuşatılmış, kibar bir soru. Mülakat, müşteri hizmetleri ve üstlerle konuşma gibi resmî ortamlarda yaygındır. -아/어요? ile sormaktan daha az doğrudan duyulur.",
forms:[["Fiil","하는지요 · 있는지요 · 했는지요"],["Sıfat","괜찮은지요 · 바쁘신지요"],["İsim","학생인지요 · 언제인지요"]],
rules:["-는지 ile aynı biçimler: fiil -는지요, sıfat -(으)ㄴ지요, geçmiş -았/었는지요.",
"Sık sık saygı eki -(으)시- ile: <b>어떻게 되시는지요?</b>",
"Soru sözcükleriyle tipiktir: 언제, 어떻게, 왜, 무엇.",
"Yükselen tonlama. Kariyer fuarları ve mülakatlar için çok kullanışlı bir ifade biçimi."],
ex:[["실례지만 지원 자격이 어떻게 **되는지요**?","Affedersiniz, başvuru koşullarının neler olduğunu sorabilir miyim?"],
["외국인도 **지원할 수 있는지요**?","Acaba yabancılar da başvurabiliyor mu?"],
["면접은 언제 **보는지요**?","Mülakatın ne zaman olduğunu sorabilir miyim?"]]},
{f:"-는 경우에",en:"X durumunda; X olursa",
core:"Varsayımsal ya da belirli bir durum kurar ve o durumda ne olacağını veya ne yapılması gerektiğini söyler. -(으)면'den daha resmîdir; kurallarda, duyurularda ve talimatlarda yaygındır.",
forms:[["Fiil (şimdiki)","지원하는 경우에 · 늦는 경우에"],["Fiil (geçmiş/tamamlanmış)","합격한 경우에 · 잃어버린 경우에"],["Sıfat","급한 경우에 · 어려운 경우에"],["İsim","N의 경우에 / N인 경우에 (외국인의 경우에)"]],
rules:["Fiil şimdiki -는, geçmiş -(으)ㄴ, sıfat -(으)ㄴ, isim <b>N의 경우(에)</b> ya da <b>N인 경우(에)</b>.",
"에 sık sık düşer: <b>-는 경우</b>.",
"Sık sık 만약, 혹시 ile kullanılır.",
"Resmî bir havası olduğu için iş ilanlarında yaygındır: 경력자인 경우 우대합니다."],
ex:[["면접에 **늦는 경우에는** 미리 담당자에게 연락하세요.","Mülakata geç kalacaksanız önceden yetkiliyle iletişime geçin."],
["한국어 능력 시험 4급 이상인 **경우** 우대합니다.","TOPIK 4. seviye ve üzeri olan adaylar tercih sebebidir."],
["외국인**의 경우에는** 비자 서류가 필요해요.","Yabancılar için vize belgeleri gereklidir."]]}],
v:[["답변","cevap, yanıt","대답'tan daha resmî. <b>질문에 답변하다</b>, 답변을 드리다. Mülakatlarda ve müşteri hizmetlerinde kullanılır.","면접관의 질문에 자신 있게 **답변했어요**.","Mülakatçının sorularını kendimden emin bir şekilde yanıtladım."],
["영업","satış; işletme faaliyeti","영업팀 (satış ekibi), 영업직, <b>영업 시간</b> (çalışma saatleri), 영업 중 (açık).","저는 **영업** 쪽 일에 관심이 있어요.","Satış alanındaki işlerle ilgileniyorum."],
["자격","nitelik, yeterlilik, koşul","<b>자격이 있다</b>, 지원 자격, 자격증 (sertifika), 자격을 갖추다.","이 일은 특별한 **자격**이 필요 없어요.","Bu iş özel bir nitelik gerektirmiyor."],
["지원자","başvuran, aday","지원하다 = başvurmak (支援 “destek” eş seslidir). 지원서 = başvuru formu.","올해는 **지원자**가 작년보다 많아요.","Bu yıl başvuran sayısı geçen yıldan fazla."],
["쪽","taraf, yön; alan","이쪽/저쪽, gündelik dilde bir alan: <b>마케팅 쪽 일</b>, 디자인 쪽으로. Ayrıca = sayfa.","어느 **쪽**으로 진로를 정할지 고민 중이에요.","Kariyerimde hangi yöne gideceğimi düşünüyorum."],
["대하다","davranmak; (N에 대해) hakkında","<b>N에 대해(서)</b> = hakkında, ile ilgili. <b>사람을 친절하게 대하다</b> = insanlara nazik davranmak.","회사에 **대해서** 궁금한 점이 있으면 물어보세요.","Şirket hakkında merak ettiğiniz bir şey varsa sorun."]],
x:[["가치관","değerler, dünya görüşü","<b>가치관이 다르다 / 맞다</b>. Yargıya yön veren değerler.","결혼할 때는 **가치관**이 잘 맞는 게 중요해요.","Evlenirken değerlerin uyuşması önemlidir."],
["근무지","iş yeri, görev yeri","Çalışılan yer: 근무지가 서울이다, 근무지 변경.","**근무지**가 집에서 너무 멀어서 고민이에요.","İş yeri evden çok uzak olduğu için kararsızım."],
["발전","gelişme, ilerleme","<b>발전하다</b>, 발전 가능성 (gelişme potansiyeli), 경제 발전.","이 회사는 **발전** 가능성이 높아 보여요.","Bu şirketin gelişme potansiyeli yüksek görünüyor."],
["복지","refah; çalışan hakları, yan haklar","사내 복지, <b>복지가 좋다</b>. Sosyal refah için de: 복지 정책.","월급보다 **복지**를 더 중요하게 생각해요.","Yan hakları maaştan daha önemli buluyorum."],
["연봉","yıllık maaş","<b>연봉이 높다</b>, 연봉 협상 (maaş pazarlığı). 월급 = aylık maaş.","**연봉**은 회사 규정에 따릅니다.","Maaş, şirket yönetmeliğine göre belirlenir."]]}]});
GUIDE.tr.push({n:5,t:"생활 속의 경제",en:"Gündelik hayatta ekonomi",units:[
{n:1,t:"소비 형태",g:[
{f:"-는걸요",en:"ama aslında…; (hafif itiraz ya da fark etme)",
core:"Karşıdakinin söylediğine, onun görüşüne ya da beklentisine ters düşen bir gerçeği öne sürerek nazikçe itiraz eder. Doğrudan karşı çıkmaktan daha yumuşaktır. İkinci kullanım: o an fark edilen bir şeye karşı hafif şaşkınlık ya da hayranlık.",
forms:[["Fiil (şimdiki zaman)","가는걸요 · 먹는걸요"],["Sıfat (şimdiki zaman)","비싼걸요 · 많은걸요"],["있다 / 없다","재미있는걸요 · 없는걸요"],["Geçmiş zaman (hepsi)","갔는걸요 · 비쌌는걸요"],["İsim","3만 원인걸요 · 학생이었는걸요"]],
rules:["Alçalan ya da düz tonlama.",
"<b>-(으)ㄹ걸요</b> ile karıştırmayın; o, yükselen tonlamalı bir tahmindir: 아마 자고 있을걸요?",
"Yalnızca bildirme cümlelerinde kullanılır; soru ya da rica için kullanılmaz.",
"Çoğunlukla 그래도, 그런데, 벌써 ile gelir; bunlar “ama aslında” havasını güçlendirir.",
"Samimi 존댓말. Bir amire ya da öğretmene bu şekilde karşı çıkmak biraz küstahça duyulabilir.",
"Ders kitaplarında bitişik yazılır: -는걸요."],
ex:[["A: 이 가방 사지 그래요? B: 너무 **비싼걸요**.","A: Neden bu çantayı almıyorsun? B: Ama çok pahalı ki."],
["그래도 새로 사는 것보다 대여하는 게 더 **저렴한걸요**.","Yine de kiralamak, yenisini almaktan daha ucuz."],
["생각보다 요리를 잘하**는걸요**!","Vay, beklediğimden iyi yemek yapıyorsun!"]]},
{f:"-게요?",en:"(yani) …mı yapacaksın? / o zaman …mı demek istiyorsun?",
core:"Dinleyicinin niyetini ya da söylediği şeyin mantıksal sonucunu soran bir soru. İki yaygın kullanım: (1) “Ne yapacaksın / ne için kullanacaksın?” (뭐 하게요?) (2) “O zaman …mı olacak?” Ima edilen bir sonucu, çoğu zaman şaşkınlıkla sorgular.",
forms:[["Fiil kökü","하게요? · 사게요? · 먹게요? · 버리게요?"]],
rules:["받침 olsun olmasın: fiil kökü + 게요? Yükselen tonlama.",
"Esas olarak dinleyicinin niyeti ya da planı için kullanılır. Konuşmada, çoğunlukla 왜, 뭐, 어떻게, 그럼 ile birlikte kullanın.",
"<b>뭐 하게요?</b> = “Ne için?” Biri bir şey ödünç almak ya da satın almak istediğinde çok yaygındır.",
"<b>그럼 + -게요?</b> bir sonucu sorgular: 그럼 혼자 다 먹게요?",
"Samimi biçim: <b>-게?</b>"],
ex:[["A: 돈 좀 빌려줄 수 있어요? B: 갑자기 왜요? 뭐 **사게요**?","A: Bana biraz borç verebilir misin? B: Birdenbire neden? Ne alacaksın?"],
["이 소파를 그냥 **버리게요**? 수거료도 내야 하는데요.","Bu kanepeyi öylece atacak mısın? Toplama ücreti de ödemen gerekecek ama."],
["그렇게 다 사면 이번 달 생활비는 어떻게 **하게요**?","Bunların hepsini alırsan bu ayki geçim masraflarını ne yapacaksın?"]]}],
v:[["수거료","toplama ücreti","Çöp ya da büyük eşyaların alınması için: 대형 폐기물 수거료. 수거하다 = toplamak. -료 = ücret (사용료, 수수료).","냉장고를 버리려면 **수거료**를 내야 해요.","Buzdolabını atmak için toplama ücreti ödemeniz gerekiyor."],
["대여하다","kiralamak, kiraya vermek; ödünç vermek","빌리다’nın resmî ya da ticari karşılığı. Kiralama hizmetleri: 자전거/정장 대여.","여행 갈 때 캐리어를 **대여했어요**.","Seyahatim için bir valiz kiraladım."],
["들이다²","harcamak (para, zaman, emek)","<b>돈/시간/공/노력을 들이다</b>. 돈을 들이지 않고 = para harcamadan. (들이다¹ = 습관을 들이다.)","돈을 많이 **들이지** 않고 방을 꾸몄어요.","Odamı çok para harcamadan dekore ettim."],
["아쉽다","yazık, üzücü; eksik kalan","Hafif bir hayal kırıklığı: bir şey eksik kaldı ya da çok erken bitti. ㅂ düzensiz: 아쉬워요. 후회하다 kadar güçlü değil.","세일이 어제 끝나서 **아쉬워요**.","İndirimin dün bitmesi çok yazık."],
["저렴하다","ucuz, uygun fiyatlı","싸다’nın kibar, nötr karşılığı; “kalitesiz” çağrışımı yoktur. Reklamlarda yaygındır.","이 가게는 품질도 좋고 가격도 **저렴해요**.","Bu dükkânın hem kalitesi iyi hem fiyatları uygun."],
["포함되다","dahil olmak","<b>N에 포함되다</b>, 배송비 포함 (kargo dahil). Geçişli: 포함하다.","가격에 세금이 **포함돼** 있어요?","Vergi fiyata dahil mi?"]],
x:[["고가","yüksek fiyat","高價. 고가의 제품, 고가 브랜드. Karşıtı: 저가.","**고가**의 물건일수록 꼼꼼히 비교해 보세요.","Ürün ne kadar pahalıysa o kadar dikkatli karşılaştırın."],
["공급","arz","공급하다, 공급이 부족하다. 수요 ile birlikte kullanılır.","**공급**이 줄어서 가격이 올랐어요.","Arz azaldı, bu yüzden fiyatlar yükseldi."],
["생산","üretim","생산하다, 대량 생산 (seri üretim), 생산자 (üretici).","이 공장에서는 하루에 천 개를 **생산**해요.","Bu fabrika günde bin adet üretiyor."],
["수요","talep","<b>수요와 공급</b> (arz ve talep). 수요가 늘다/많다.","여름에는 에어컨 **수요**가 많아요.","Yazın klimaya talep yüksektir."],
["저가","düşük fiyat","低價. <b>저가 항공</b> (düşük maliyetli havayolu), 저가 상품.","**저가** 항공을 이용하면 싸게 여행할 수 있어요.","Düşük maliyetli havayollarını kullanırsanız ucuza seyahat edebilirsiniz."],
["구매하다","satın almak","사다’nın resmî karşılığı. 구매자 (alıcı), 온라인 구매, 구매 후기 (ürün yorumu).","온라인으로 **구매하면** 할인을 받을 수 있어요.","İnternetten satın alırsanız indirim alabilirsiniz."]]},
{n:2,t:"결제 방식",g:[
{f:"-었어야 하다",en:"…malıydı, …meliydim",
core:"Geçmişte yapılmamış bir şey için pişmanlık ya da eleştiri bildirir: “X yapmalıydım.” Olumsuzu: <b>-지 말았어야 하다</b> = yapmamalıydım. Türkçedeki “-malıydı” ekine çok benzer.",
forms:[["Fiil, ㅏ/ㅗ","샀어야 했다 · 왔어야 했다"],["Fiil, diğer","먹었어야 했다 · 확인했어야 했다"],["Olumsuz","사지 말았어야 했다"]],
rules:["Genellikle <b>-었어야 했어요</b> (geçmişe dair pişmanlık) ya da <b>-었어야 해요</b> (şimdi söylenen “yapmalıydın”) olarak biter.",
"Kendin hakkında = pişmanlık. Başkaları hakkında = eleştiri ya da sitem.",
"Çoğunlukla 미리, 진작, 그때 ile birlikte kullanılır.",
"Anlamca -(으)ㄹ걸 그랬다’ya (keşke yapsaydım) yakındır; o daha yumuşak ve kişiseldir."],
ex:[["할부로 사기 전에 이자를 **확인했어야 했어요**.","Taksitle almadan önce faizi kontrol etmeliydim."],
["그렇게 비싼 걸 충동적으로 **사지 말았어야 했는데**.","O kadar pahalı bir şeyi dürtüsel olarak almamalıydım."],
["간편 결제 앱을 미리 **설치했어야 했어요**.","Mobil ödeme uygulamasını önceden yüklemeliydim."]]},
{f:"-다가 보면",en:"X yapmaya devam edersen (sonunda) Y",
core:"Genel bir tahmin ya da tavsiye: bir eyleme zamanla devam etmek bir sonuca götürür. Çoğu zaman cesaretlendirici (“alışırsın”) ya da uyarıcıdır (“fazla harcarsın”).",
forms:[["Fiil","쓰다(가) 보면 · 살다(가) 보면 · 하다(가) 보면"]],
rules:["Yalnızca fiillerle. 가 çoğu zaman düşer: <b>-다 보면</b>.",
"İkinci cümle gelecek, genel ya da tavsiye bildirir: -게 될 거예요, -(으)ㄹ 수 있어요, -기 마련이에요, -아/어요.",
"İkinci cümlede geçmiş zaman olmaz. Geçmişteki sonuçlar için <b>-다 보니까</b> kullanın (1과).",
"Cesaret vermek için ideal: 계속 하다 보면 잘하게 될 거예요."],
ex:[["카드를 생각 없이 **쓰다 보면** 돈이 금방 없어져요.","Kartı düşünmeden kullanmaya devam edersen paran çabucak biter."],
["처음엔 어렵지만 **사용하다 보면** 익숙해질 거예요.","İlk başta zor ama kullandıkça alışırsın."],
["한국에 **살다 보면** 이런 일이 종종 생겨요.","Kore’de yaşarken böyle şeyler arada bir olur."]]}],
v:[["가맹점","anlaşmalı mağaza, franchise şubesi","Franchise şubeleri ya da belirli bir kartı veya ödeme yöntemini kabul eden mağazalar: <b>가맹점 할인</b>, 카드 가맹점.","이 카드는 **가맹점**에서 10% 할인돼요.","Bu kart anlaşmalı mağazalarda %10 indirim sağlıyor."],
["시스템","sistem","Alıntı kelime, Türkçedeki “sistem” gibi kullanılır: 결제 시스템, 시스템을 도입하다.","새 결제 **시스템** 때문에 처음에는 좀 헷갈렸어요.","Yeni ödeme sistemi yüzünden ilk başta biraz kafam karıştı."],
["표시","işaret, etiket, gösterge","<b>표시하다</b>, 가격 표시 (fiyat etiketi), 표시가 되어 있다. Duyguları göstermek için de: 감사의 표시.","카드 사용 가능 **표시**가 있는 가게에서만 돼요.","Yalnızca kart kabul edildiğine dair işaret olan mağazalarda geçiyor."],
["도입하다","(bir sistem ya da politika) getirmek, uygulamaya koymak","Sistem ya da politika getirmek için: <b>제도/시스템을 도입하다</b>. İnsanları tanıştırmak için kullanılmaz (o 소개하다).","그 식당은 키오스크 주문을 **도입했어요**.","O restoran kiosk ile sipariş sistemine geçti."],
["당분간","şimdilik, bir süreliğine","<b>당분간 -(으)ㄹ 예정이다</b>. Geçici bir dönem: 당분간 휴업 (geçici olarak kapalı).","공사 때문에 **당분간** 현금만 받습니다.","İnşaat nedeniyle şimdilik yalnızca nakit kabul ediyoruz."],
["이래저래","şu ya da bu sebeple; şundan bundan","Birkaç küçük sebebin birleşimi: <b>이래저래 바쁘다 / 돈이 들다</b>.","이번 달은 **이래저래** 돈 쓸 일이 많았어요.","Bu ay şu ya da bu sebeple para harcamam gereken çok şey oldu."]],
x:[["선불","peşin ödeme, ön ödeme","先拂. 선불로 내다, <b>선불 카드</b> (ön ödemeli kart), 선불 요금제.","이 식당은 **선불**이에요. 먼저 계산하세요.","Bu restoranda ödeme önceden yapılıyor. Lütfen önce ödeyin."],
["할부","taksitli ödeme","<b>3개월 할부로 사다</b>. Karşıtı: 일시불 (tek çekim). Kasiyerler sorar: 일시불로 해 드릴까요?","노트북을 6개월 **할부**로 샀어요.","Dizüstü bilgisayarı altı taksitle aldım."],
["후불","sonradan ödeme","後拂. 후불 교통카드, 후불 결제.","이 교통카드는 **후불**이라서 다음 달에 돈이 나가요.","Bu ulaşım kartı sonradan ödemeli, o yüzden para gelecek ay çekiliyor."],
["지불하다","ödemek","Resmî ya da yazı dili: <b>요금/비용을 지불하다</b>. Gündelik dilde: 내다, 계산하다.","현금으로 **지불하면** 할인해 드려요.","Nakit öderseniz indirim yapıyoruz."],
["가상 계좌 입금","sanal hesaba havale","Kore’de internet alışverişinde yaygın ödeme yöntemi: para göndermek için geçici bir banka hesap numarası. 입금하다 = para yatırmak.","**가상 계좌**로 **입금**하면 주문이 완료돼요.","Sanal hesaba para yatırdığınızda sipariş tamamlanır."],
["간편 결제","kolay / mobil ödeme","카카오페이, 네이버페이, 삼성페이 gibi mobil ödeme hizmetleri.","요즘은 지갑 없이 **간편 결제**로 다 해요.","Bu aralar her şeyi cüzdansız, mobil ödemeyle hallediyorum."]]}]});

GUIDE.tr.push({n:6,t:"의사소통과 표현",en:"İletişim ve ifade",units:[
{n:1,t:"불평과 불만",g:[
{f:"까지",en:"bile (üstüne üstlük)",
core:"Temel anlamı olan “-e kadar”ın ötesinde 까지 “bile” anlamına da gelebilir: bir listeye aşırı ya da beklenmedik bir şey ekler, çoğu zaman şikâyet ederken. “Yetmezmiş gibi X bile.”",
forms:[["İsim","너까지 · 주말까지 · 밤늦게까지"],["Diğer ilgeçlerle","나한테까지 · 동생까지도"]],
rules:["İsimlere eklenir ve başka ilgeçlerle üst üste gelebilir: <b>나한테까지</b>.",
"Çoğunlukla bir şikâyet listesinin ardından gelir: 비도 오고 바람도 불고, 우산<b>까지</b> 잃어버렸어요.",
"마저 ve 조차’ya benzer. 까지 olumlu ya da olumsuz olabilir; 조차 ve 마저 genellikle olumsuzdur.",
"Vurgu için 도 eklenebilir: <b>까지도</b>."],
ex:[["옆집 사람이 음악을 크게 틀고, 밤에는 노래**까지** 불러요.","Komşum müziği sonuna kadar açıyor, geceleri şarkı bile söylüyor."],
["친구가 약속에 늦었는데 사과**까지** 안 했어요.","Arkadaşım buluşmaya geç kaldı, üstelik özür bile dilemedi."],
["가족들**까지** 제 말을 무시하니까 정말 속상해요.","Ailem bile söylediklerimi duymazdan geliyor, bu beni gerçekten üzüyor."]]},
{f:"-더라고요",en:"(gördüm / fark ettim ki) X (kişisel gözlem)",
core:"Konuşanın geçmişte bizzat gördüğü, duyduğu ya da hissettiği bir şeyi dinleyiciye yeni bilgi olarak aktarır. “Gördüm ki…” ya da “Biliyor musun, …ymış” gibi duyulur.",
forms:[["Fiil / sıfat","가더라고요 · 맛있더라고요 · 불친절하더라고요"],["Tamamlanmış geçmiş","끝났더라고요 · 왔더라고요"],["İsim","학생이더라고요 · 외국인이더라고요"]],
rules:["Kök + 더라고요. Geçmiş -았/었더라고요 = gördüğümde çoktan olmuştu.",
"Doğrudan deneyime dayanır. Yalnızca başkasından duyduğunuz şeyler için kullanılamaz (onun için -대요).",
"Normalde kendi eylemleriniz için kullanılmaz (“Ben gittim” ✗ 제가 가더라고요); kendi duygu ya da tepkileriniz hariç: 저도 모르게 눈물이 <b>나더라고요</b>.",
"Samimi biçim: <b>-더라</b>."],
ex:[["그 식당 직원이 정말 **불친절하더라고요**.","O restoranın çalışanları gerçekten kabaydı."],
["가서 보니까 이미 문을 **닫았더라고요**.","Gittiğimde çoktan kapatmışlardı."],
["지하철에서 큰 소리로 통화하는 사람이 **많더라고요**.","Metroda yüksek sesle telefonda konuşan çok insan vardı."]]}],
v:[["매너","görgü, nezaket kuralları","Gündelik Korecede yaygın alıntı kelime: <b>매너가 좋다 / 없다</b>, 비매너 (görgüsüzlük), 매너 있게.","공공장소에서는 **매너**를 지켜야 해요.","Kamusal alanlarda görgü kurallarına uymalısınız."],
["무시하다","görmezden gelmek; küçümsemek","İki anlamı var: umursamamak (말을 무시하다) ve aşağılamak (사람을 무시하다). İkincisi daha güçlü ve çok kırıcıdır.","제 의견을 계속 **무시해서** 기분이 나빴어요.","Fikrimi sürekli görmezden geldiği için canım sıkıldı."],
["배려하다","düşünceli davranmak, gözetmek","<b>N을/를 배려하다</b>, 배려심 (düşüncelilik). Kore’de temel bir sosyal değer.","다른 사람을 **배려하는** 마음이 중요해요.","Başkalarını düşünen bir tutum önemlidir."],
["불쾌하다","tatsız, rahatsız olmuş, hoşnutsuz","기분 나쁘다’dan daha resmî ya da güçlü. 불쾌감 = hoşnutsuzluk.","반말을 들어서 좀 **불쾌했어요**.","Bana 반말 ile konuşulunca biraz rahatsız oldum."],
["지나치다","(1) aşırı; (2) geçip gitmek","(1) Sıfat: 지나친 간섭, 지나치게 (aşırı derecede). (2) Fiil: 정류장을 지나치다 (durağı kaçırmak).","그건 좀 **지나친** 행동이었던 것 같아요.","Bence o biraz aşırı bir davranıştı."],
["가만히","hareketsizce, sessizce; hiçbir şey yapmadan","<b>가만히 있다</b> = kıpırdamamak ya da tepki vermeden sessiz kalmak. 가만히 두다 = kendi hâline bırakmak.","부당한 일을 당하면 **가만히** 있지 말고 말하세요.","Haksızlığa uğrarsanız sessiz kalmayın, sesinizi çıkarın."]],
x:[["갈등","çatışma, anlaşmazlık","<b>갈등이 생기다</b>, 갈등을 해결하다/해소하다. 세대 갈등 (kuşak çatışması).","룸메이트와 청소 문제로 **갈등**이 생겼어요.","Ev arkadaşımla temizlik yüzünden anlaşmazlık yaşadım."],
["감정","duygu, his","<b>감정을 표현하다 / 조절하다 / 숨기다</b>, 감정적 (duygusal).","화가 나도 **감정**을 조절하려고 노력해요.","Kızgın olsam bile duygularımı kontrol etmeye çalışırım."],
["의사","niyet, irade","(Doktor anlamındaki 의사 değil.) <b>의사를 전달하다 / 밝히다</b>, 의사소통. Resmî.","분명하게 자기 **의사**를 표현하는 게 좋아요.","Niyetinizi açıkça ifade etmek iyidir."],
["해소","giderme, çözüm","Stres ya da çatışma için: <b>스트레스 해소</b>, 갈등 해소, 해소하다.","저는 운동으로 스트레스를 **해소**해요.","Stresimi sporla atıyorum."],
["간섭하다","karışmak, burnunu sokmak","<b>N에 간섭하다</b>, 사생활에 간섭하다. Olumsuz.","제 일에 너무 **간섭하지** 마세요.","Lütfen işlerime bu kadar karışmayın."],
["겪다","yaşamak, (zorluk) çekmek","Zorluklar için kullanılır: <b>어려움 / 갈등 / 문화 차이를 겪다</b>. 경험하다 daha nötrdür.","처음 한국에 왔을 때 문화 차이를 많이 **겪었어요**.","Kore’ye ilk geldiğimde çok kültür şoku yaşadım."],
["전달하다","iletmek, aktarmak","<b>메시지/의견/마음을 전달하다</b>. Edilgen: 전달되다 (9과).","제 마음이 잘 **전달됐으면** 좋겠어요.","Umarım duygularım iyi anlaşılır."],
["피하다","kaçınmak, sakınmak","<b>N을/를 피하다</b>, 비를 피하다, 눈을 피하다. 피할 수 없다 = kaçınılmaz.","싸우기 싫어서 그 사람을 **피했어요**.","Kavga etmek istemediğim için o kişiden uzak durdum."]]},
{n:2,t:"위로와 격려",g:[
{f:"-는지",en:"nasıl / …ıp …madığı / ne… (iç soru)",
core:"Bir soruyu daha büyük bir cümlenin içinde yan cümleye çevirir: “Ne kadar zor olduğunu biliyorum,” “…ıp …madığını bilmiyorum.” Teselli ve cesaretlendirmede çoğunlukla 얼마나 ile birlikte duygudaşlık gösterir: 얼마나 힘든지 알아요. Türkçedeki “-dığını” yan cümlelerine benzer.",
forms:[["Fiil","하는지 · 했는지 · 할지 (gelecek)"],["Sıfat","힘든지 · 속상한지 · 힘들었는지"],["İsim","누구인지 · 무엇인지"]],
rules:["Fiil şimdiki zaman -는지, sıfat -(으)ㄴ지, geçmiş -았/었는지, gelecek -(으)ㄹ지.",
"Ardından bilmek, merak etmek ya da sormak fiilleri gelir: 알다, 모르다, 궁금하다, 물어보다, 생각하다.",
"<b>얼마나 -는지 모르다</b> = “ne kadar … bilemezsin” (vurgulu): 얼마나 걱정했는지 몰라요.",
"Zaman bildiren <b>-(으)ㄴ 지</b> (boşluklu) ile karıştırmayın; o “…den beri” demektir: 한국에 온 지 3년 됐어요."],
ex:[["네가 지금 얼마나 **속상한지** 잘 알아.","Şu an ne kadar üzgün olduğunu çok iyi biliyorum."],
["시험 결과가 나왔다는 얘기를 듣고 얼마나 **걱정했는지** 몰라요.","Sınav sonuçlarının açıklandığını duyunca ne kadar endişelendiğimi bilemezsin."],
["무엇이 문제**인지** 같이 생각해 봐요.","Sorunun ne olduğunu birlikte düşünelim."]]},
{f:"-겠지요",en:"herhalde / mutlaka X, değil mi? (umutlu varsayım)",
core:"Konuşanın tahmini (-겠-) ile onay arayışının (-지요) birleşimi. Teselli ve cesaretlendirmede umutlu bir beklentiyi ifade eder: “Her şey mutlaka düzelir, değil mi?” Karşıdakinin duygularını anlayışla tahmin etmek için de kullanılır.",
forms:[["Şimdiki / gelecek zaman","좋아지겠지요 · 힘들겠지요"],["Geçmiş zaman","힘들었겠지요 · 놀랐겠지요"],["İsim","학생이겠지요"]],
rules:["Kök + 겠지요. Geçmiş: <b>-았/었겠지요</b> (…mış olmalı).",
"Kısaltılmış <b>-겠죠</b> konuşmada çok yaygındır.",
"Teselli: <b>곧 괜찮아지겠지요</b>. Empati: <b>많이 힘들었겠지요</b>.",
"-(으)ㄹ 거예요’dan daha az kesindir. Dinleyiciyi onaylamaya davet eder."],
ex:[["열심히 했으니까 좋은 결과가 **있겠지요**.","Çok çalıştın, mutlaka iyi bir sonuç alırsın."],
["떨어져서 많이 **속상했겠지요**. 다음에는 꼭 붙을 거예요.","Kalınca çok üzülmüşsündür. Bir dahakine kesinlikle geçeceksin."],
["시간이 지나면 다 **괜찮아지겠죠**.","Zamanla her şey düzelir, değil mi?"]]}],
v:[["심정","ruh hâli, iç dünya","마음 ya da 기분’den daha ağır ve resmî. <b>그 심정 이해해요</b> (ne hissettiğini anlıyorum). 답답한 심정.","시험에 떨어진 친구의 **심정**을 알 것 같아요.","Sınavdan kalan arkadaşımın ne hissettiğini anlıyorum sanırım."],
["연속","art arda, üst üste","<b>3년 연속</b>, 연속으로, 연속해서.","면접에서 세 번 **연속**으로 떨어졌어요.","Mülakatlardan üst üste üç kez elendim."],
["의욕","istek, şevk, motivasyon","<b>의욕이 생기다 / 없다 / 넘치다</b>, 의욕을 잃다. 동기’dan (sebep) çok harekete geçme enerjisi gibidir.","요즘 아무것도 하기 싫고 **의욕**이 없어요.","Bu aralar hiçbir şey yapmak istemiyorum. Hiç şevkim yok."],
["따다","elde etmek, kazanmak; koparmak","Yeterlilik ya da başarı elde etmek: <b>자격증 / 점수 / 메달을 따다</b>. Ayrıca 과일을 따다 (meyve toplamak).","드디어 운전면허를 **땄어요**!","Sonunda ehliyetimi aldım!"],
["딱","tam olarak; sadece; kesin bir şekilde","<b>딱 한 번</b> (sadece bir kez), 딱 맞다 (tam oturmak), 딱 잘라 말하다 (kesin bir dille söylemek). Çok yaygın.","**딱** 한 번만 더 해 보세요.","Sadece bir kez daha deneyin."],
["분명히","açıkça; kesinlikle, mutlaka","Hem açıklık (분명히 말하다) hem kesinlik (분명히 잘될 거예요).","너는 **분명히** 잘할 수 있을 거야.","Sen kesinlikle başarılı olacaksın."]],
x:[["격려하다","cesaretlendirmek","<b>N을/를 격려하다</b>, 격려의 말, 격려를 받다.","선생님이 저를 많이 **격려해** 주셨어요.","Öğretmenim beni çok cesaretlendirdi."],
["공감하다","empati kurmak, kendini özdeşleştirmek","<b>N에 공감하다</b>, 공감 능력, 공감이 가다 (insanın kendinden bir şey bulması).","친구의 이야기에 정말 **공감했어요**.","Arkadaşımın anlattıklarında kendimi gerçekten buldum."],
["속상하다","üzgün, kırgın, canı sıkkın","Gündelik duygusal acı ya da hayal kırıklığı. Çok yaygın, 화나다’dan daha yumuşak.","열심히 준비했는데 결과가 안 좋아서 **속상해요**.","Çok çalışıp hazırlandım ama sonuç kötü olunca üzüldüm."],
["우울하다","depresif, kasvetli, moralsiz","Gündelik ruh hâli (비가 와서 우울해요) ve klinik anlam (우울증 = depresyon).","날씨가 흐리면 기분이 **우울해져요**.","Hava kapalı olunca moralim bozuluyor."],
["지치다","bitkin düşmek, yorgun düşmek","Genellikle zamanla fiziksel ya da duygusal olarak tükenmek: <b>일에 지치다</b>, 지친 몸. 피곤하다’dan daha güçlü.","매일 야근을 해서 너무 **지쳤어요**.","Her gün fazla mesai yapıyorum, tamamen tükendim."]]}]});
GUIDE.tr.push({n:7,t:"일상생활",en:"Günlük yaşam",units:[
{n:1,t:"공공질서",g:[
{f:"-도록²",en:"…acak kadar; …ana kadar",
core:"Derece veya ölçü bildirir: ana eylem o kadar çok (ya da o kadar uzun süre) yapıldı ki 도록 cümlesindeki durum gerçekleşti. Genellikle geçen bir zamanı ya da gözle görülür, fiziksel bir sonucu anlatır. Türkçedeki “sesim kısılana kadar”, “sabaha kadar” yapısına benzer.",
forms:[["Fiil / sıfat kökü","새도록 · 넘도록 · 쉬도록 · 아프도록"]],
rules:["받침 olsun olmasın kök + 도록.",
"도록 cümlesi zaman eki almaz: asla 지났도록 ya da 쉬었도록 denmez.",
"Zamanın geçmesi: <b>밤이 새도록</b>, 밤늦도록, 몇 시간이 지나도록.",
"Dereceyi gösteren fiziksel sonuç: <b>목이 쉬도록</b>, 배가 터지도록, 눈물이 나도록.",
"Sık sık olumsuzla birlikte: “X olmasına rağmen hâlâ … değil”: 한 시간이 지나도록 연락이 없어요.",
"도록 cümlesinin genellikle kendi öznesi vardır (목이, 밤이).",
"Kalıplaşmış ifadeler: 죽도록, 귀가 따갑도록, 입이 닳도록.",
"“…sın diye” anlamında amaç bildiren -도록¹ (2. ders) ile karıştırmayın."],
ex:[["옆집 개가 밤이 **새도록** 짖어서 한숨도 못 잤어요.","Komşunun köpeği sabaha kadar havladı, gözümü bile kırpamadım."],
["목이 **쉬도록** 노래를 불렀어요.","Sesim kısılana kadar şarkı söyledim."],
["30분이 **지나도록** 버스가 안 와요.","Otuz dakika geçti, otobüs hâlâ gelmedi."]]},
{f:"만이라도",en:"hiç değilse (sadece) X",
core:"만 (sadece) + 이라도 (…olsa bile). Konuşanın kabul edeceği ya da istediği asgari düzeyi belirtir: “Hepsi olmasa da hiç değilse X.”",
forms:[["İsim","조금만이라도 · 한 번만이라도 · 주말만이라도"],["Fiil (-기만이라도 ile)","듣기만이라도 · 와 주기만이라도"]],
rules:["İsimlere ya da miktar ifadelerine eklenir: <b>한 번만이라도</b>, 오늘만이라도, 5분만이라도.",
"Fiillerle: <b>-기만이라도 하다</b>: 얼굴을 보기만이라도 하고 싶어요.",
"İkinci cümle genellikle rica, dilek veya öneridir: -아/어 주세요, -(으)면 좋겠다, -아/어야지요.",
"İdeal olanın daha fazlası olduğunu, ama bu asgari düzeyin kabul edilebilir olduğunu ima eder."],
ex:[["다른 건 몰라도 공공장소에서**만이라도** 조용히 해 주세요.","Başka bir şey istemiyorum ama hiç değilse halka açık yerlerde sessiz olun."],
["반려동물을 산책시킬 때 목줄**만이라도** 꼭 해 주세요.","Evcil hayvanınızı gezdirirken hiç değilse tasma takın lütfen."],
["바쁘더라도 **하루에 10분만이라도** 운동하세요.","Meşgul olsanız bile günde hiç değilse 10 dakika egzersiz yapın."]]}],
v:[["목줄","tasma","Evcil hayvanlar için: <b>목줄을 하다 / 채우다</b>. Kore’de köpeklere halka açık yerlerde tasma takmak yasal zorunluluktur.","공원에서는 반려견에게 **목줄**을 꼭 해야 해요.","Parkta köpeğinize mutlaka tasma takmalısınız."],
["반려동물","evcil hayvan, can dostu","Artık 애완동물 yerine tercih edilir (o kelime “oyuncak” çağrışımı yapar). 반려견 = köpek, 반려묘 = kedi.","**반려동물**을 키우는 사람이 점점 늘고 있어요.","Evcil hayvan besleyenlerin sayısı giderek artıyor."],
["다가오다","yaklaşmak","Fiziksel (사람이 다가오다) ya da zaman (시험이 다가오다). Karşıtı: 멀어지다.","큰 개가 갑자기 **다가와서** 깜짝 놀랐어요.","Büyük bir köpek aniden yanıma geldi, çok korktum."],
["짖다","havlamak","Köpekler için: <b>개가 짖다</b>. 멍멍 짖다.","밤마다 옆집 개가 **짖어서** 시끄러워요.","Komşunun köpeği her gece havlıyor, çok gürültülü."],
["책임지다","sorumluluk almak, üstlenmek","<b>N을/를 책임지다</b>. 책임 = sorumluluk (책임감, 10. ders).","반려동물을 키우면 끝까지 **책임져야** 해요.","Evcil hayvan besliyorsanız sonuna kadar sorumluluğunu almalısınız."],
["마구","gelişigüzel, rastgele, ölçüsüzce","Özensizce ya da aşırı yapılan şey: <b>마구 버리다 / 뛰다 / 먹다</b>. Konuşma dilindeki 막 ile aynı.","길에 쓰레기를 **마구** 버리면 안 돼요.","Sokağa gelişigüzel çöp atmamalısınız."],
["몇몇","birkaç, bazı (kişi ya da şey)","<b>몇몇 사람들</b>. 일부 gibi. Sayı vermeden küçük bir grubu işaret eder.","**몇몇** 사람들 때문에 공원이 더러워졌어요.","Birkaç kişi yüzünden park kirlendi."],
["오히려","aksine, tam tersine","Beklenenin tersi bir sonuç: “Düzeleceğine daha da kötüleşti.”","사과는커녕 **오히려** 저한테 화를 냈어요.","Özür dilemek şöyle dursun, tam tersine bana kızdı."]],
x:[["공공질서","kamu düzeni","<b>공공질서를 지키다</b> (kamu düzenine uymak).","모두가 **공공질서**를 지키면 살기 좋은 사회가 돼요.","Herkes kamu düzenine uyarsa yaşanacak güzel bir toplum olur."],
["고성방가하다","yüksek sesle şarkı söyleyip bağırarak gürültü yapmak","高聲放歌. Çoğunlukla gece sarhoşlar için kullanılır; yasal bir suç da olabilir.","밤늦게 **고성방가하는** 사람들 때문에 잠을 못 잤어요.","Gece geç saatte bağırıp şarkı söyleyen insanlar yüzünden uyuyamadım."],
["새치기하다","sıraya kaynak yapmak","<b>줄을 서다</b> (sıraya girmek) ve 새치기하다. Çok kaba sayılır.","줄을 서 있는데 누가 **새치기했어요**.","Sırada bekliyordum, biri önüme kaynak yaptı."],
["무단 횡단하다","kurallara aykırı karşıdan karşıya geçmek","무단 = izinsiz, 횡단 = geçiş. 횡단보도 = yaya geçidi.","**무단 횡단하면** 위험하고 벌금도 내야 해요.","Yaya geçidi dışından karşıya geçmek tehlikelidir, ceza da ödersiniz."],
["신경을 쓰다","dikkat etmek, önemsemek; kafaya takmak","<b>N에 신경(을) 쓰다</b>. 신경 쓰지 마세요 = boş verin, dert etmeyin. 신경이 쓰이다 = kafasını kurcalamak.","다른 사람에게 피해를 주지 않도록 **신경을 써야** 해요.","Başkalarını rahatsız etmemeye dikkat etmelisiniz."]]},
{n:2,t:"맛집",g:[
{f:"-길래",en:"X olduğunu görünce / duyunca Y yaptım",
core:"Konuşanın fark ettiği ya da duyduğu bir şeye dayanan sebep, ardından konuşanın tepkisi veya eylemi gelir. Doğal ve konuşma diline özgüdür: “X’i gördüm, ben de Y yaptım.”",
forms:[["Fiil / sıfat","맛있길래 · 사람이 많길래 · 하길래"],["Geçmiş","왔길래 · 끝났길래"],["İsim","맛집이길래 · 세일이길래"]],
rules:["Kök + 길래. Geçmiş: -았/었길래.",
"Sebep genellikle konuşanın dışındadır (başka biri, bir durum). Sonuç konuşanın kendi eylemidir.",
"İkinci cümle emir veya öneri olamaz (✗ 맛있길래 가세요). Bunun için -(으)니까 kullanın.",
"Sebep soran sorularda da kullanılır: <b>뭘 먹었길래</b> 배가 아파요? (Ne yedin de karnın ağrıyor?)"],
ex:[["줄이 **길길래** 맛집인 줄 알고 저도 서 봤어요.","Sıra uzundu, iyi bir lokanta sandım, ben de sıraya girdim."],
["입소문이 **났길래** 한번 가 봤는데 정말 맛있더라고요.","Adı dilden dile dolaşıyordu, ben de bir gidip denedim, gerçekten çok lezzetliydi."],
["도대체 뭘 **넣었길래** 이렇게 고소해요?","Allah aşkına içine ne koydun da bu kadar lezzetli olmuş?"]]},
{f:"-던걸요",en:"bence X’ti ama (hatırlama + karşı görüş)",
core:"-더- (konuşanın yaşadığını hatırlama) ile -ㄴ걸요 (hafif itiraz veya şaşkınlık, 5. ders) birleşimidir. Konuşan, geçmişteki kişisel izlenimini aktarır; bu izlenim çoğu zaman dinleyenin beklentisine ters düşer. Türkçedeki “-mişti ama / -dı ki” tonuna yakındır.",
forms:[["Fiil / sıfat","맛있던걸요 · 사람이 많던걸요 · 잘하던걸요"],["Tamamlanmış geçmiş","닫았던걸요 · 끝났던걸요"],["İsim","맛집이던걸요"]],
rules:["Kök + 던걸요. Tamamlanmış geçmiş: -았/었던걸요.",
"Doğrudan deneyime dayanır. Kendiniz görmüş ya da tatmışsınızdır.",
"Çoğu zaman itiraz eder veya şaşırtır: A: 그 집 별로래요. B: 저는 <b>맛있던걸요</b>.",
"Karşılaştırın: -는걸요 (şimdiki olgu) ve -던걸요 (o zaman yaşadığım bir şey)."],
ex:[["A: 그 식당 비싸지 않아요? B: 아니요, 생각보다 **저렴하던걸요**.","A: O lokanta pahalı değil mi? B: Yok, sandığımdan ucuzdu ama."],
["어제 가 보니까 벌써 문을 **닫았던걸요**.","Dün gittiğimde çoktan kapanmıştı ama."],
["처음엔 느끼할 줄 알았는데 의외로 **담백하던걸요**.","Önce ağır olur sanmıştım ama şaşırtıcı derecede hafifti."]]}],
v:[["비결","sır (başarının), püf noktası","<b>N의 비결</b>, 맛의 비결, 성공 비결. Saklanan bir sır değil (o 비밀), anahtar bir teknik.","이 집 김치찌개 맛의 **비결**이 뭐예요?","Bu lokantanın kimçi güvecinin sırrı ne?"],
["입소문","ağızdan ağıza yayılma, kulaktan kulağa","<b>입소문이 나다</b> (adı duyulmak), 입소문을 타다 (ağızdan ağıza yayılmak).","그 빵집은 **입소문**이 나서 손님이 많아졌어요.","O fırının adı ağızdan ağıza yayıldı, artık çok müşterisi var."],
["최근","son zamanlarda; en son","<b>최근에</b>, 최근 몇 년 (son birkaç yıl), 최근 뉴스. 요즘’den daha resmîdir.","**최근**에 이 근처에 새 식당이 생겼어요.","Son zamanlarda buraya yakın yeni bir lokanta açıldı."],
["고소하다","fındıksı, kavrulmuş lezzetli (susam vb.)","Susam yağı, kavrulmuş kuruyemiş ya da taze ekmek tadı. Eğlenceli ek anlamları: “oh olsun” (başkasının başına gelene sevinme) ve sesteş 고소하다 = dava açmak.","참기름을 넣으니까 **고소해요**.","Susam yağı koyunca mis gibi kavrulmuş bir tat oldu."],
["꼽히다","(arasında) sayılmak","<b>N(으)로 꼽히다</b>, 최고의 맛집으로 꼽히다. Etken: 꼽다.","이곳은 서울 최고의 냉면집으로 **꼽혀요**.","Burası Seul’ün en iyi naengmyeon lokantalarından biri sayılıyor."],
["담백하다","hafif, sade (yağlı ya da ağır olmayan)","Basit, yağsız yemekler için olumlu bir tat sözcüğü. Kişilik için de kullanılır (sade, gösterişsiz).","이 국물은 기름기가 없어서 **담백해요**.","Bu çorba yağsız, o yüzden hafif ve sade."],
["붐비다","kalabalık olmak","<b>사람들로 붐비다</b>. İnsanlar için değil, yerler için: 식당이 붐비다.","점심시간에는 식당이 직장인들로 **붐벼요**.","Öğle saatinde lokanta çalışanlarla dolup taşıyor."],
["색다르다","alışılmadık, farklı, değişik","İlginç ve yeni anlamında farklı. Olumlu: <b>색다른 맛 / 경험</b>.","오늘은 **색다른** 음식을 먹어 보고 싶어요.","Bugün değişik bir şey yemek istiyorum."]],
x:[["느끼하다","yağlı, ağır; (kişi) yapmacık, yılışık","Yemek: aşırı yağlı ya da kremalı (çoğunlukla olumsuz). Kişi: 느끼한 말 = yılışık, yapmacık laf.","크림 파스타는 좀 **느끼해서** 많이 못 먹어요.","Kremalı makarna biraz ağır, o yüzden çok yiyemem."],
["매콤하다","hoş acı, acımsı","Hafif ve iştah açıcı acılık. 맵다’dan daha yumuşak ve olumlu.","**매콤한** 떡볶이가 먹고 싶어요.","Canım acılı tteokbokki çekti."],
["비리다","balık kokulu, ağır kokulu","Hoş olmayan balık ya da çiğ kokusu veya tadı: 생선이 비리다, 비린내.","이 생선은 하나도 안 **비리네요**.","Bu balık hiç kokmuyor."],
["새콤하다","hoş ekşi, mayhoş","İştah açıcı ekşilik. Sık sık 새콤달콤 (ekşi tatlı).","**새콤한** 레몬 소스가 잘 어울려요.","Mayhoş limon sosu çok iyi gidiyor."],
["쌉쌀하다","hafif acı (tat olarak)","Hoş, hafif acılık: 녹차, 도라지, 다크 초콜릿. 쓰다’dan daha yumuşak.","이 차는 맛이 좀 **쌉쌀해요**.","Bu çayın tadı biraz acımsı."],
["짭짤하다","tuzlu ve lezzetli; (para) kârlı","Yemek: hoş tuzlu. Argo: 짭짤한 수입 = dolgun bir gelir.","감자칩은 **짭짤해서** 자꾸 손이 가요.","Patates cipsi tuzlu olduğu için elim sürekli ona gidiyor."]]}]});

GUIDE.tr.push({n:8,t:"문제와 해결",en:"Sorunlar ve çözümler",units:[
{n:1,t:"고장과 수리",g:[
{f:"-는다 -는다 하는 것이",en:"X yapacağım yapacağım derken (hâlâ yapmadım)",
core:"Fiilin tekrarı, konuşanın bir şeyi yapmaya sürekli niyet ettiğini ya da yapacağını söylediğini ama yine de yapmadığını gösterir. Erteleme itiraf ederken sık kullanılır. Türkçedeki “yapacağım yapacağım derken” yapısıyla neredeyse birebir örtüşür.",
forms:[["Fiil, 받침 yok","고친다 고친다 하는 것이 · 간다 간다 하는 것이"],["Fiil, 받침 var","읽는다 읽는다 하는 것이"],["Kısa","-는다 -는다 하는 게"]],
rules:["Aynı fiil iki kez -ㄴ/는다 düz biçiminde.",
"Ardından genellikle geçmiş zamanlı olumsuz ya da bir sonuç gelir: 아직 못 했어요, 결국 잊어버렸어요, 벌써 한 달이 지났어요.",
"Konuşma biçimi: <b>-ㄴ다 -ㄴ다 하는 게</b>.",
"Kendini sorgulayan ya da özür diler bir ton."],
ex:[["세면대를 **고친다 고친다 하는 것이** 벌써 한 달이 지났어요.","Lavaboyu tamir edeceğim edeceğim derken bir ay geçti bile."],
["전화**한다 한다 하는 게** 계속 잊어버렸어요.","Arayacağım arayacağım derken hep unuttum."],
["운동을 **시작한다 시작한다 하는 것이** 아직도 못 했어요.","Spora başlayacağım başlayacağım derken hâlâ başlayamadım."]]},
{f:"-는 수밖에 없다",en:"X’ten başka çare yok",
core:"Mevcut tek seçenek. 수 = yol/çare, 밖에 없다 = …’den başka yok. “…mekten başka çarem yok.”",
forms:[["Fiil, 받침 yok","교체하는 수밖에 없다 · 사는 수밖에 없다"],["Fiil, 받침 var","참는 수밖에 없다 · 기다리는 수밖에"]],
rules:["Fiil + -는 수밖에 없다 (gelecek ya da geçmiş durumlar için bile şimdiki zaman biçimi).",
"Geçmiş: <b>-는 수밖에 없었다</b> (…mekten başka çare yoktu).",
"Çoğunlukla bir sebebin ardından: 고칠 수 없으니까 새로 <b>사는 수밖에 없어요</b>.",
"Benzeri: -(으)ㄹ 수밖에 없다 = ister istemez, kaçınılmaz olarak (daha çok doğal sonuç). İkisi de 4급’ta geçer."],
ex:[["너무 낡아서 새것으로 **교체하는 수밖에 없어요**.","Çok eskimiş, yenisiyle değiştirmekten başka çare yok."],
["주말이라 수리 기사님이 안 오셔서 월요일까지 **기다리는 수밖에 없었어요**.","Hafta sonu olduğu için tamirci gelmedi, pazartesiye kadar beklemekten başka çarem yoktu."],
["열쇠를 잃어버렸으니 열쇠 기사님을 **부르는 수밖에 없겠네요**.","Anahtarımı kaybettim, çilingir çağırmaktan başka çare yok galiba."]]}],
v:[["세면대","lavabo (banyo)","Yüz ya da el yıkamak için. Mutfak evyesi = 싱크대.","**세면대**에서 물이 새요.","Banyo lavabosundan su sızıyor."],
["키","anahtar","Anahtar ve kartlı anahtar için alıntı sözcük: 카드 키, 차 키. Yerli sözcük 열쇠’dır. (Sesteş 키 = boy.)","현관 **키**를 집 안에 두고 나왔어요.","Kapı anahtarını evin içinde bırakıp çıktım."],
["교체하다","değiştirmek (parça)","<b>N을/를 N(으)로 교체하다</b>, 부품/배터리를 교체하다. Eskiyi yenisiyle değiştirmek.","고장 난 전구를 새것으로 **교체했어요**.","Bozuk ampulü yenisiyle değiştirdim."],
["부르다","çağırmak (birini gelmesi için)","<b>수리 기사를 부르다</b>, 택시를 부르다. Ayrıca: şarkı söylemek (노래를 부르다), karnı doymak (배가 부르다).","보일러가 고장 나서 기사님을 **불렀어요**.","Kombi bozuldu, tamirci çağırdım."],
["새다","sızmak, akıtmak","<b>물/가스가 새다</b>. Ayrıca: 밤을 새다 (sabahlamak). 빛이 새다.","천장에서 물이 **새서** 집주인에게 연락했어요.","Tavandan su sızıyordu, ev sahibine haber verdim."],
["다 되다","bitmek, tükenmek; hazır olmak","<b>배터리가 다 되다</b> (şarjı bitmek), 수명이 다 되다 (ömrünü doldurmak), 밥이 다 되다 (pilav hazır).","휴대폰 배터리가 **다 돼서** 전화를 못 했어요.","Telefonumun şarjı bitti, arayamadım."]],
x:[["나가다","(elektrik) kesilmek; (ampul) yanmak, patlamak","“Dışarı çıkmak” dışında: <b>전기가 나가다</b> (elektrik kesintisi), 전구가 나가다.","갑자기 전기가 **나가서** 깜깜해졌어요.","Elektrik birden kesildi, zifiri karanlık oldu."],
["낡다","eski, yıpranmış","Yalnızca eşyalar için, kullanımdan: <b>낡은 집 / 옷</b>. İnsanlar için 늙다. 오래되다 = eski (zaman olarak).","집이 **낡아서** 고칠 데가 많아요.","Ev eski, o yüzden tamir edilecek çok yeri var."],
["설치하다","kurmak, yüklemek","<b>에어컨/프로그램을 설치하다</b>. Ekipman kurmak için de kullanılır.","새 에어컨을 **설치하는** 데 하루가 걸렸어요.","Yeni klimayı kurmak bir gün sürdü."],
["손보다","elden geçirmek, onarmak","Gündelik dil: ufak tamir ya da rötuş. <b>문을 좀 손보다</b>.","오래된 자전거를 좀 **손봐서** 다시 타요.","Eski bisikletimi biraz elden geçirdim, yeniden biniyorum."],
["금이 가다","çatlamak","<b>유리/벽에 금이 가다</b>. Mecazi: 우정에 금이 가다 (dostluk çatlamak).","휴대폰 화면에 **금이 갔어요**.","Telefonumun ekranı çatladı."]]},
{n:2,t:"이웃 간의 문제",g:[
{f:"-는 바람에",en:"(beklenmedik bir olay) yüzünden, (kötü sonuç)",
core:"Beklenmedik ya da istenmeyen bir olay genellikle olumsuz bir sonuca yol açtı. -아/어서’a benzer ama olayın aniden ya da elde olmadan gerçekleştiğini vurgular.",
forms:[["Fiil","오는 바람에 · 쿵쿵거리는 바람에 · 고장 나는 바람에"]],
rules:["Yalnızca fiillerle, geçmiş olaylar için bile hep şimdiki -는 biçimi: 비가 <b>오는 바람에</b> 늦었어요.",
"Sonuç cümlesi geçmiş zamandadır: -았/었어요.",
"Sonuç cümlesinde emir ya da öneri olmaz.",
"Sonuç genellikle olumsuzdur. Olumlu sonuç mümkündür ama ironik ya da şans eseri gibi durur: 버스를 놓치는 바람에 오히려 친구를 만났어요."],
ex:[["윗집에서 밤늦게 **쿵쿵거리는 바람에** 잠을 못 잤어요.","Üst kattakiler gece geç saatte güm güm yürüdüğü için uyuyamadım."],
["옆집 사람이 차를 막아 **놓는 바람에** 회사에 늦었어요.","Komşum arabamın önünü kapattığı için işe geç kaldım."],
["갑자기 물이 **새는 바람에** 아랫집에 피해를 끼쳤어요.","Birden su sızınca alt kattaki daireye zarar verdim."]]},
{f:"-어서야",en:"(1) ancak X’ten sonra; (2) X böyleyken nasıl… (retorik)",
core:"İki kullanımı var. (1) <b>Ancak … olunca / …ene kadar değil</b>: bir şey ancak X’ten sonra oldu. (2) <b>Retorik şikâyet</b>: “Durum X böyleyken Y nasıl mümkün olsun?” -겠어요? ya da -(으)ㄹ 수 있겠어요? ile kullanılır. Bu ikinci kullanım 이웃 문제 durumlarında yaygındır.",
forms:[["Fiil / sıfat, ㅏ/ㅗ","와서야 · 많아서야"],["Fiil / sıfat, diğer","들어서야 · 시끄러워서야"],["하다","해서야 · 조용해서야"]],
rules:["(1) Ancak …’ten sonra: 밤 12시가 <b>넘어서야</b> 조용해졌어요. Sık sık 겨우, 비로소, 그제야 ile.",
"(2) Retorik: <b>이렇게 시끄러워서야</b> 잠을 잘 수 있겠어요? Cevap açıkça “hayır”dır.",
"-어서야 geçmiş zaman eki almaz.",
"Retorik kullanım güçlü ama dolaylı bir şikâyettir. Komşuya kibar ama kararlı bir not yazmak için uygundur."],
ex:[["관리실에 항의를 하고 **나서야** 소음이 멈췄어요.","Gürültü ancak yönetim ofisine şikâyet ettikten sonra kesildi."],
["밤마다 이렇게 **시끄러워서야** 어떻게 살 수 있겠어요?","Her gece bu kadar gürültü varken insan nasıl yaşasın?"],
["주차를 이렇게 **해서야** 다른 사람들이 어떻게 지나가요?","Böyle park ederseniz başkaları nasıl geçsin?"]]}],
v:[["요청하다","talep etmek, rica etmek","Resmî rica: <b>N에게 N을/를 요청하다</b>, 도움을 요청하다, 협조 요청.","관리실에 수리를 **요청했어요**.","Yönetim ofisinden tamir talep ettim."],
["웬만하다","fena değil, idare eder; katlanılabilir","Sıfat: <b>웬만한 일</b> = sıradan ya da ufak işler. Zarf <b>웬만하면</b> = mümkünse, çok zahmet olmazsa.","**웬만하면** 밤 10시 이후에는 세탁기를 돌리지 마세요.","Mümkünse akşam 10’dan sonra çamaşır makinesini çalıştırmayın."],
["쿵쿵거리다","güm güm etmek, gümbürdemek","Yansıma sözcük 쿵쿵 + -거리다 (tekrarlanan ses ya da hareket). Her 층간 소음 (katlar arası gürültü) şikâyetinde geçer.","윗집 아이들이 뛰어서 천장이 **쿵쿵거려요**.","Üst kattaki çocuklar koşuyor, tavan güm güm ediyor."],
["항의하다","itiraz etmek, şikâyette bulunmak","<b>N에게 항의하다</b>. 불평하다’dan daha güçlü ve resmîdir; sorumlu kişiye yöneliktir.","소음 때문에 윗집에 **항의했어요**.","Gürültü yüzünden üst kattakilere şikâyette bulundum."],
["도대체","Allah aşkına, ne diye","Sinirli soruları güçlendirir: <b>도대체 왜 / 뭐 / 언제</b>.","**도대체** 몇 시까지 시끄럽게 할 거예요?","Allah aşkına saat kaça kadar gürültü yapacaksınız?"],
["종종","sık sık, ara sıra","Arada bir ama oldukça düzenli. 가끔 ile 자주 arası.","아파트에서는 이런 문제가 **종종** 생겨요.","Apartmanlarda bu tür sorunlar ara sıra çıkar."]],
x:[["손해","zarar (genellikle maddi)","<b>손해를 보다</b> (zarar etmek), 손해를 입다. Karşıtı: 이익.","싸게 팔아서 **손해**를 봤어요.","Ucuza sattım, zarar ettim."],
["피해","zarar, hasar (başkalarına)","<b>피해를 주다 / 끼치다 / 입다</b>, 피해자 (mağdur). 손해’dan daha geniş anlamlı.","다른 사람에게 **피해**를 주지 않도록 조심하세요.","Başkalarına zarar vermemeye dikkat edin."],
["끼치다","(sıkıntı, zarar) vermek","Çoğunlukla kalıp ifadelerde: <b>폐를 끼치다</b> (rahatsız etmek), 피해를 끼치다, 영향을 끼치다.","늦게까지 시끄럽게 해서 폐를 **끼쳐** 죄송합니다.","Geç saate kadar gürültü yapıp sizi rahatsız ettiğim için özür dilerim."],
["따지다","hesap sormak, açıklama istemek; tartmak","(1) Biriyle yüzleşmek: 왜 그랬냐고 따지다. (2) Dikkatle hesaplamak: 장단점을 따지다.","참다못해 윗집에 가서 **따졌어요**.","Daha fazla dayanamayıp üst kata çıktım ve hesap sordum."],
["무책임하다","sorumsuz","무- (-sız) + 책임. 무책임한 행동. Türkçedeki “-sız” ekiyle aynı mantık.","쓰레기를 아무 데나 버리는 건 **무책임한** 행동이에요.","Çöpü her yere atmak sorumsuz bir davranıştır."],
["요구하다","talep etmek, istemek (hak olarak)","요청하다’dan (rica) daha güçlü: hakkınız olarak istersiniz. 요구 사항.","피해에 대한 보상을 **요구했어요**.","Zarar için tazminat talep ettim."],
["위반하다","ihlal etmek, çiğnemek","Kurallar ya da yasalar için: <b>규칙/법/교통 신호를 위반하다</b>.","주차 규칙을 **위반하면** 벌금을 내야 해요.","Park kurallarını ihlal ederseniz ceza ödemeniz gerekir."],
["저지르다","(hata, suç) işlemek","Olumsuz eylemler: <b>실수/잘못/범죄를 저지르다</b>. 르 düzensiz: 저질러요.","제가 큰 실수를 **저질렀어요**.","Büyük bir hata yaptım."]]}]});
GUIDE.tr.push({n:9,t:"정보화 사회",en:"Bilgi toplumu",units:[
{n:1,t:"가짜 뉴스",g:[
{f:"에 비해서",en:"N’ye kıyasla, N’ye göre",
core:"Bir şeyi bir referans noktasıyla karşılaştırır. Resmî bir tınısı vardır; yazı dilinde, haberlerde ve TOPIK kompozisyonlarında çok yaygındır.",
forms:[["İsim","예전에 비해서 · 작년에 비해 · 신문에 비해서"],["Fiil (-는 것에 ile)","노력하는 것에 비해서 · 가격에 비해서"]],
rules:["<b>N에 비해(서)</b>. Yazı dilinde 서 çoğu zaman düşer: 에 비해.",
"Ana cümlede genellikle karşılaştırma bildiren bir sıfat bulunur, çoğu zaman 더 ya da 훨씬 ile: 예전에 비해 정보가 훨씬 많아졌다.",
"<b>N에 비해 + sıfat</b> “N’ye göre, N’ye oranla” anlamına gelebilir: 가격에 비해 품질이 좋다 (fiyatına göre kalitesi iyi).",
"Eş anlamlısı: N보다. 에 비해서 daha resmî ve analitiktir."],
ex:[["인터넷 뉴스는 신문**에 비해서** 정보가 빨리 전달돼요.","İnternet haberleri, gazetelere kıyasla bilgiyi daha hızlı iletir."],
["예전**에 비해** 가짜 뉴스가 훨씬 많아졌어요.","Eskiye kıyasla sahte haberler çok arttı."],
["이 기사는 길이**에 비해서** 내용이 별로 없어요.","Bu makalenin uzunluğuna göre pek içeriği yok."]]},
{f:"-을 수가 있어야지요",en:"X’i nasıl yapayım ki (imkânsız) — yakınma",
core:"Retorik bir yakınma: konuşan X’i yapmak istemiş ya da denemiştir, ama koşullar yüzünden mümkün olmamıştır. Kelimesi kelimesine “X’i yapabiliyor olmak gerekir ki”, yani “ama yapamıyorum”.",
forms:[["Fiil, 받침 yok","볼 수가 있어야지요 · 잘 수가 있어야지요"],["Fiil, 받침 var","믿을 수가 있어야지요 · 읽을 수가 있어야지요"]],
rules:["Fiil + -(으)ㄹ 수가 있어야지요. Kısa biçimi: <b>-(으)ㄹ 수가 있어야죠</b>.",
"Genellikle sebep söylendikten sonra gelir: 너무 시끄러워서 잠을 <b>잘 수가 있어야지요</b>.",
"Hayal kırıklığı bildirir; bahane ya da şikâyet gibi duyulur.",
"Daha geniş bir kalıp olan <b>-아/어야지요</b> da vardır (“X olması gerekirdi, ama değil”): 말이 통해야지요."],
ex:[["가짜 뉴스가 너무 많아서 뭘 **믿을 수가 있어야지요**.","O kadar çok sahte haber var ki neye inanayım ki?"],
["기사가 너무 전문적이라서 **이해할 수가 있어야지요**.","Makale o kadar teknik ki kim anlayabilir ki?"],
["광고가 계속 나와서 영상을 **볼 수가 있어야지요**.","Reklamlar durmadan çıkıyor, videoyu izleyemiyorum bile."]]}],
v:[["난리","kargaşa, velvele, curcuna","<b>난리가 나다</b> = ortalık birbirine girmek. Çoğu zaman abartılı kullanılır: SNS에서 난리가 났어요 (sosyal medyada olay oldu, ortalık karıştı).","그 가짜 뉴스 때문에 인터넷이 **난리**가 났어요.","O sahte haber yüzünden internette ortalık birbirine girdi."],
["여부","olup olmadığı","Resmî isim: <b>사실 여부</b> (doğru olup olmadığı), 참석 여부, 합격 여부.","기사를 공유하기 전에 사실 **여부**를 확인하세요.","Bir haberi paylaşmadan önce doğru olup olmadığını kontrol edin."],
["의심","şüphe, kuşku","<b>의심하다</b>, 의심스럽다, 의심이 들다 (şüphelenmek).","출처가 없는 기사는 **의심**해 봐야 해요.","Kaynağı olmayan haberlerden şüphelenmek gerekir."],
["작업","iş, çalışma, işlem","Belirli bir iş ya da süreç: 편집 작업, 작업 중, 작업하다. 일’den daha somuttur.","영상 편집 **작업**에 시간이 많이 걸려요.","Video kurgu işi çok zaman alıyor."],
["전문적","profesyonel, uzmanlık gerektiren, teknik","-적 ismi: 전문적인 지식, 전문적으로. 전문가 = uzman.","이 내용은 **전문적**이라서 이해하기 어려워요.","Bu içerik teknik olduğu için anlaşılması zor."],
["가리다","ayırt etmek; örtmek, kapatmak; seçici olmak","(1) <b>진실을 가리다</b>, 옳고 그름을 가리다. (2) 얼굴을 가리다 (yüzünü kapatmak). (3) 음식을 가리다 (yemek seçmek).","어떤 뉴스가 진짜인지 **가리기**가 어려워요.","Hangi haberin gerçek olduğunu ayırt etmek zor."],
["넘쳐나다","taşmak, dolup taşmak","Bir şeyin fazlasıyla olması: <b>정보가 넘쳐나다</b>.","인터넷에는 정보가 **넘쳐나요**.","İnternet bilgiyle dolup taşıyor."],
["전달되다","iletilmek, aktarılmak","전달하다’nın edilgeni (6과). <b>정보/메시지가 전달되다</b>.","SNS로 소식이 순식간에 **전달돼요**.","Haberler sosyal medyada bir anda yayılıyor."]],
x:[["분석하다","analiz etmek, çözümlemek","데이터를 분석하다, 분석 결과.","전문가들이 그 기사를 **분석했어요**.","Uzmanlar o haberi analiz etti."],
["삭제하다","silmek","<b>파일/게시물을 삭제하다</b>. Günlük dilde: 지우다.","가짜 뉴스는 결국 **삭제됐어요**.","Sahte haber sonunda silindi."],
["입력하다","girmek (veri)","<b>비밀번호/정보를 입력하다</b>.","아이디와 비밀번호를 **입력하세요**.","Kullanıcı adınızı ve şifrenizi girin."],
["저장하다","kaydetmek, depolamak","<b>파일을 저장하다</b>, 저장 공간 (depolama alanı).","작업한 파일을 꼭 **저장하세요**.","Üzerinde çalıştığınız dosyayı mutlaka kaydedin."],
["전송하다","göndermek, iletmek (veri)","<b>파일/메시지를 전송하다</b>. 보내다’dan daha tekniktir.","사진을 이메일로 **전송했어요**.","Fotoğrafı e-postayla gönderdim."]]},
{n:2,t:"휴대 전화 사용 제한",g:[
{f:"에 따르면",en:"N’ye göre",
core:"Bilginin kaynağını belirtir. Hemen hemen her zaman ardından aktarılan söz gelir (-ㄴ/는다고 하다, -대요, -(이)래요).",
forms:[["İsim","뉴스에 따르면 · 조사에 따르면 · 전문가에 따르면"]],
rules:["<b>N에 따르면 + -ㄴ/는다고 해요 / -대요</b>: aktarma biçimi beklenir. Türkçedeki “-mIş” ya da “diyor” gibi düşünebilirsiniz.",
"N bir kaynaktır: 뉴스, 신문, 조사 결과, 연구, 전문가, 친구 말.",
"Resmîdir; bu yüzden sunumlarda, kompozisyonlarda ve haberlerde çok yaygındır.",
"에 따라(서) ile karıştırmayın = -e bağlı olarak / -e uygun olarak."],
ex:[["조사**에 따르면** 학생의 70%가 휴대 전화 사용 제한에 반대한다고 해요.","Bir ankete göre öğrencilerin %70’i telefon kullanımının kısıtlanmasına karşıymış."],
["뉴스**에 따르면** 내년부터 수업 중 휴대폰 사용이 금지된대요.","Haberlere göre seneye ders sırasında telefon kullanımı yasaklanacakmış."],
["전문가**에 따르면** 자기 전에 휴대폰을 보는 것은 수면에 방해가 된다고 합니다.","Uzmanlara göre yatmadan önce telefona bakmak uykuyu bozuyormuş."]]},
{f:"-는다고 보다",en:"X olarak görmek / X olduğunu düşünmek (görüş)",
core:"Bir görüş ya da yargı bildirir; çoğu zaman resmî ve analitiktir: “Bence…”, “… olduğu kanısındayım.” Tartışmalarda ve görüş yazılarında yaygındır.",
forms:[["Fiil","필요하다고 보다 · 제한해야 한다고 보다 · 간다고 보다"],["Sıfat","중요하다고 보다 · 옳다고 보다"],["İsim","문제라고 보다 · 권리라고 보다"]],
rules:["Dolaylı aktarma biçimlerini kullanır: fiil -ㄴ/는다고, sıfat -다고, isim -(이)라고.",
"<b>저는 -다고 봐요 / 봅니다</b>: görüş bildirmenin -다고 생각해요’dan daha yumuşak ve daha nesnel duyulan bir yolu.",
"Edilgen anlamlı biçimi: <b>-다고 볼 수 있다</b> (… olduğu söylenebilir).",
"토론 (münazara) ifadelerinde çok işe yarar."],
ex:[["저는 학교에서 휴대 전화 사용을 어느 정도 **제한해야 한다고 봅니다**.","Bence okulda telefon kullanımı bir ölçüde kısıtlanmalı."],
["휴대폰을 마음대로 쓰는 것도 학생의 **권리라고 봐요**.","Telefonu istediği gibi kullanmayı da öğrencinin hakkı olarak görüyorum."],
["이 문제는 학생과 선생님이 함께 합의하는 게 가장 **중요하다고 봐요**.","Bu konuda en önemli şeyin öğrencilerle öğretmenlerin birlikte uzlaşması olduğunu düşünüyorum."]]}],
v:[["권리","hak","<b>권리가 있다</b>, 권리를 주장하다/지키다. 의무 (görev, yükümlülük) ile birlikte kullanılır.","누구나 자유롭게 의견을 말할 **권리**가 있어요.","Herkesin fikrini özgürce söyleme hakkı vardır."],
["인권","insan hakları","<b>인권 침해</b> (insan hakları ihlali), 인권을 보호하다.","휴대폰을 강제로 걷는 것은 **인권** 침해라고 주장하는 사람도 있어요.","Telefonları zorla toplamanın insan hakları ihlali olduğunu savunanlar da var."],
["의견","görüş, fikir","<b>의견을 말하다 / 나누다 / 제시하다</b>, 의견이 다르다.","이 문제에 대해서 여러분의 **의견**은 어때요?","Bu konuda sizin görüşünüz nedir?"],
["판단","yargı, karar","<b>판단하다</b>, 판단을 내리다, 스스로 판단하다. 판단력 (10과).","학생들도 스스로 **판단**할 수 있는 능력이 있어요.","Öğrencilerin de kendi başlarına karar verebilme yeteneği var."],
["제한하다","kısıtlamak, sınırlamak","<b>사용/시간/속도를 제한하다</b>. 제한 시간 (süre sınırı).","학교에서 휴대폰 사용 시간을 **제한하고** 있어요.","Okul telefon kullanım süresini kısıtlıyor."],
["합의하다","uzlaşmak, anlaşmaya varmak","İki taraf tartıştıktan sonra anlaşır: <b>N와 합의하다</b>, 합의를 보다. Karşılaştırın: 동의하다 (bir görüşe katılmak).","학생회와 학교가 규칙에 **합의했어요**.","Öğrenci konseyi ve okul kurallar üzerinde uzlaştı."],
["마음대로","istediği gibi, keyfince","Nötr (serbestçe) ya da olumsuz (izin almadan) olabilir. <b>마음대로 하세요</b> = nasıl isterseniz öyle yapın.","수업 시간에 휴대폰을 **마음대로** 쓰면 안 돼요.","Ders sırasında telefonu istediğin gibi kullanamazsın."]],
x:[["대립","karşıtlık, çatışma","Karşı taraflar: <b>의견이 대립하다</b>, 찬반 대립.","이 문제에 대해서 의견이 **대립**하고 있어요.","Bu konuda görüşler ikiye bölünmüş durumda."],
["동의","onay, katılma, rıza","<b>N에 동의하다</b> (-e katılmak), 동의를 구하다 (onay istemek).","저도 그 의견에 **동의**해요.","Ben de o görüşe katılıyorum."],
["방안","önlem, plan, (çözüm) yolu","Resmî: <b>해결 방안을 마련하다 / 제시하다</b>.","문제를 해결할 수 있는 **방안**을 찾아야 해요.","Sorunu çözebilecek bir yol bulmamız gerek."],
["토론","münazara, tartışma","Taraflar lehte ya da aleyhte savunur (찬성 / 반대). Karşılaştırın: 토의.","오늘 수업에서 휴대폰 사용에 대해 **토론**했어요.","Bugün derste telefon kullanımını tartıştık."],
["토의","müzakere, görüş alışverişi (iş birliğiyle)","Bir grup çözüm bulmak için birlikte konuşur. 토론 = karşıt taraflar; 토의 = birlikte bir cevaba doğru çalışmak.","학급 회의에서 규칙에 대해 **토의**했어요.","Sınıf toplantısında kurallar üzerine görüştük."],
["마련하다","hazırlamak, sağlamak (para, önlem)","<b>대책/방안/돈/자리를 마련하다</b>. Bir şeyi çoğu zaman emek harcayarak hazır etmek.","학교는 새로운 규칙을 **마련했어요**.","Okul yeni kurallar hazırladı."],
["설득하다","ikna etmek","<b>N을/를 설득하다</b>, 설득력 (ikna gücü).","부모님을 **설득하는** 게 쉽지 않았어요.","Ailemi ikna etmek kolay olmadı."],
["제시하다","sunmak, ortaya koymak","<b>의견/방안/근거를 제시하다</b>. Resmî; kompozisyonlarda ve tartışmalarda.","주장을 할 때는 근거를 **제시해야** 해요.","Bir iddiada bulunurken kanıt sunmanız gerekir."]]}]});

GUIDE.tr.push({n:10,t:"현대인의 모습",en:"Modern insan",units:[
{n:1,t:"현대인과 일",g:[
{f:"만 아니면",en:"N olmasa; bir N olmasa",
core:"만 (yalnızca) + 아니면 (değilse). Konuşan, bir şeyi engelleyen tek engeli belirtir: “Bir X olmasa, … yapabilirdim.”",
forms:[["İsim","일만 아니면 · 시험만 아니면 · 회사만 아니면"],["Fiil (-는 것만 ile)","야근하는 것만 아니면"]],
rules:["İsimlere eklenir: <b>N만 아니면</b>.",
"İkinci cümle, engel olmasa mümkün olacak şeyi anlatır: -(으)ㄹ 텐데, -았/었을 거예요, -(으)ㄹ 수 있을 텐데.",
"Çoğu zaman özlem ya da yakınma tonu taşır.",
"Geçmişteki durum için: <b>N만 아니었으면</b> (N olmasaydı)."],
ex:[["야근**만 아니면** 이 회사가 정말 좋을 텐데요.","Bir fazla mesai olmasa, bu şirket gerçekten harika olurdu."],
["내일 발표**만 아니면** 오늘 같이 놀 수 있을 텐데.","Yarınki sunum olmasa, bugün seninle takılabilirdim."],
["그 실수**만 아니었으면** 좋은 성과를 거둘 수 있었을 거예요.","O hata olmasaydı, iyi sonuçlar alabilirdik."]]},
{f:"-는 듯이",en:"-mış gibi; sanki X",
core:"Bir eylemin nasıl yapıldığını bir şeye benzeterek anlatır: “-mış gibi”, “sanki”. Çoğu zaman edebî ya da canlı bir anlatımdır. -는 것처럼’e benzer.",
forms:[["Fiil (şimdiki zaman)","죽은 듯이 · 기다렸다는 듯이 · 아무 일도 없었다는 듯이"],["Fiil","날아가는 듯이 · 쏟아지는 듯이"],["Sıfat","아픈 듯이 · 피곤한 듯이"]],
rules:["Fiil şimdiki zaman -는 듯이, geçmiş zaman -(으)ㄴ 듯이, gelecek zaman -(으)ㄹ 듯이, sıfat -(으)ㄴ 듯이.",
"이 düşebilir: <b>-는 듯</b>.",
"Aktarma biçimleriyle sık kullanılır: <b>-다는 듯이</b> (der gibi): 기다렸다는 듯이 (bekliyormuş gibi).",
"Kalıplaşmış ifadeler: 죽은 듯이 자다 (ölü gibi uyumak), 물 쓰듯이 (su gibi harcamak), 밥 먹듯이 (yemek yer gibi, yani sürekli).",
"Cümleyi bitiren -는 듯하다 (… gibi görünüyor) ile karşılaştırın."],
ex:[["그는 피곤해서 **죽은 듯이** 잤어요.","O kadar yorgundu ki ölü gibi uyudu."],
["현대인들은 야근을 **밥 먹듯이** 해요.","Modern insanlar sürekli fazla mesai yapıyor."],
["퇴근 시간이 되자 모두 **기다렸다는 듯이** 사무실을 나갔어요.","Paydos saati gelince herkes sanki bunu bekliyormuş gibi ofisten çıktı."]]}],
v:[["경쟁","rekabet","<b>경쟁하다</b>, 경쟁이 치열하다 (kızışmak), 경쟁력 (rekabet gücü, 10과-2).","요즘은 취업 **경쟁**이 정말 치열해요.","Bu aralar iş bulma rekabeti gerçekten çok kızıştı."],
["장시간","uzun saatler, uzun süre","Resmî: <b>장시간 근무 / 운전</b>. Zıt anlamlısı: 단시간.","**장시간** 앉아서 일하면 허리가 아파요.","Uzun süre oturarak çalışınca bel ağrıyor."],
["효율적","verimli","-적 ismi: 효율적인 방법, 효율적으로. 효율 = verim. 효과적 = etkili (sonuç verir); 효율적 = verimli (az israf).","시간을 **효율적**으로 쓰는 게 중요해요.","Zamanı verimli kullanmak önemli."],
["뒤떨어지다","geride kalmak, geri kalmak","<b>N에 뒤떨어지다</b>, 시대에 뒤떨어지다 (çağın gerisinde kalmak).","새로운 기술을 배우지 않으면 시대에 **뒤떨어질** 수 있어요.","Yeni teknolojiyi öğrenmezseniz çağın gerisinde kalabilirsiniz."],
["살아남다","hayatta kalmak, ayakta kalmak","Zorlu rekabet ya da ağır koşullar için: 경쟁에서 살아남다.","치열한 경쟁 속에서 **살아남으려면** 계속 공부해야 해요.","Kızışan rekabette ayakta kalmak için sürekli öğrenmeniz gerekir."],
["온종일","bütün gün, gün boyu","하루 종일 ile aynı, biraz daha edebî.","**온종일** 컴퓨터 앞에 앉아 있었어요.","Bütün gün bilgisayarın başında oturdum."]],
x:[["성과","sonuç, başarı","<b>성과를 거두다 / 올리다 / 내다</b>, 성과급 (performans primi).","이번 프로젝트에서 좋은 **성과**를 거뒀어요.","Bu projede iyi sonuçlar elde ettik."],
["현대인","modern insan","현대 (modern çağ) + -인 (kişi). Kompozisyonlarda yaygın konu: 현대인의 삶.","**현대인**은 늘 시간에 쫓기며 살아요.","Modern insan hep zamanla yarışarak yaşıyor."],
["거두다","elde etmek (sonuç); toplamak, hasat etmek","<b>성과/성공/승리를 거두다</b>. Gerçek anlamı: 곡식을 거두다 (ekin biçmek).","그 팀은 큰 성공을 **거두었어요**.","O takım büyük bir başarı elde etti."],
["깨지다","kırılmak; (rekor) kırılmak","<b>기록이 깨지다</b>, 유리가 깨지다. Mecazi olarak da: 약속이 깨지다.","그 선수 덕분에 세계 기록이 **깨졌어요**.","O sporcu sayesinde dünya rekoru kırıldı."],
["올리다","yükseltmek; elde etmek; paylaşmak (internette)","<b>성과/매출을 올리다</b>, 월급을 올리다, 사진을 올리다 (internette paylaşmak).","이번 달에 매출을 많이 **올렸어요**.","Bu ay satışları epey artırdık."],
["향하다","-e yönelmek, -e doğru gitmek","<b>N을/를 향하다</b>, N(으)로 향하다, 꿈을 향해 (hayaline doğru).","모두가 같은 목표를 **향해** 노력하고 있어요.","Herkes aynı hedefe doğru çabalıyor."]]},
{n:2,t:"현대인의 소통 수단",g:[
{f:"-는 법이다",en:"X’in olması doğaldır; X hep olur (genel doğru)",
core:"Genel bir doğruyu, doğa yasasını ya da halk bilgeliğini dile getirir: “İşin doğası bu.” Çoğu zaman teselli etmek, öğüt vermek ya da açıklamak için kullanılır.",
forms:[["Fiil","하는 법이다 · 생기는 법이다 · 있는 법이다"],["Sıfat","힘든 법이다 · 어려운 법이다"]],
rules:["Fiil -는 법이다, sıfat -(으)ㄴ 법이다. Yalnızca şimdiki zamanla.",
"Bilgece ya da atasözü gibi duyulur: <b>누구나 실수하는 법이에요</b>. Türkçedeki geniş zamanlı genel doğrulara benzer (“İnsan hata yapar.”).",
"Çoğu zaman bir koşulun ardından gelir: 노력하면 결과가 <b>있는 법이에요</b>.",
"Benzeri: -기 마련이다 (olması kaçınılmaz)."],
ex:[["처음에는 누구나 **실수하는 법이에요**.","Başta herkes hata yapar. İşin doğası bu."],
["자주 연락하지 않으면 사이가 **멀어지는 법이지요**.","Sık sık görüşmezseniz doğal olarak aranız açılır."],
["새로운 방식에는 장점과 단점이 다 **있는 법이에요**.","Her yeni yöntemin artıları da eksileri de olur."]]},
{f:"-는다고 할 수 있다",en:"X olduğu söylenebilir",
core:"Bir sonucu ya da tanımı temkinli ve nesnel biçimde ifade etmenin yolu. Kompozisyonlarda, sunumlarda ve TOPIK 쓰기’da yaygındır.",
forms:[["Fiil","변했다고 할 수 있다 · 선호한다고 할 수 있다"],["Sıfat","편리하다고 할 수 있다"],["İsim","소통 수단이라고 할 수 있다"]],
rules:["Dolaylı aktarma biçimleri: fiil -ㄴ/는다고, sıfat -다고, isim -(이)라고.",
"Resmî yazı dili üslubu: <b>-다고 할 수 있다 / 있습니다</b>.",
"Sonuç cümleleri için uygundur: 따라서 … <b>-다고 할 수 있다</b>.",
"Benzeri: -다고 볼 수 있다 (9과)."],
ex:[["스마트폰은 현대인의 가장 중요한 소통 수단**이라고 할 수 있다**.","Akıllı telefonun modern insanın en önemli iletişim aracı olduğu söylenebilir."],
["요즘 젊은 사람들은 전화보다 채팅을 **선호한다고 할 수 있어요**.","Bugünün gençlerinin aramak yerine mesajlaşmayı tercih ettiği söylenebilir."],
["이처럼 SNS는 사람들의 관계를 **바꾸었다고 할 수 있습니다**.","Bu şekilde sosyal medyanın insanların ilişkilerini değiştirdiği söylenebilir."]]}],
v:[["일부분","bir parça, bir kısım","일부 ile aynı; bir bütünün parçası olduğunu vurgular: 생활의 일부분.","휴대폰은 이제 생활의 **일부분**이 됐어요.","Telefonlar artık günlük hayatın bir parçası oldu."],
["채팅","sohbet, mesajlaşma (çevrimiçi)","Alıntı kelime: 채팅하다, 단체 채팅방 (grup sohbeti, 단톡방).","친구들과 매일 **채팅**으로 이야기해요.","Arkadaşlarımla her gün mesajlaşıyorum."],
["멀어지다","uzaklaşmak, arası açılmak","Fiziksel ya da duygusal: <b>사이가 멀어지다</b>, 친구와 멀어지다. Zıt anlamlısı: 가까워지다.","연락을 안 하다 보니 친구와 **멀어졌어요**.","Görüşmeyince arkadaşımla aramız açıldı."],
["부담스럽다","yük gibi gelen, rahatsız edici, fazla","Baskı ya da mahcubiyet hissetmek: 전화가 부담스럽다, 비싼 선물이 부담스럽다. Kore sosyal hayatında çok yaygın.","저는 갑자기 오는 전화가 좀 **부담스러워요**.","Ansızın gelen telefonlar bana biraz fazla geliyor."],
["선호하다","tercih etmek","Resmî: <b>N보다 N을/를 선호하다</b>. Günlük dilde: 더 좋아하다.","요즘은 통화보다 메시지를 **선호하는** 사람이 많아요.","Bu aralar aramak yerine mesajlaşmayı tercih eden çok insan var."],
["흔하다","yaygın, sıradan","Kolay bulunan, sık görülen: 흔한 일, 흔히 (genellikle). Zıt anlamlısı: 드물다.","요즘은 영상 통화가 아주 **흔해요**.","Bu aralar görüntülü görüşmeler çok yaygın."],
["굳이","illa ki, zahmet edip (gereksiz yere)","Gerekmeyen bir şeyi yapmak: <b>굳이 -(으)ㄹ 필요가 없다</b>, 굳이 왜? (ne gerek var?).","문자로 하면 되는데 **굳이** 전화할 필요가 있어요?","Mesajla halledebiliriz, illa aramaya ne gerek var?"]],
x:[["경쟁력","rekabet gücü","경쟁 + -력 (güç, yetenek). <b>경쟁력이 있다 / 높다</b>, 경쟁력을 키우다.","외국어 능력은 취업 **경쟁력**을 높여 줘요.","Yabancı dil becerisi iş ararken rekabet gücünüzü artırır."],
["긴장감","gerginlik, gerilim","긴장 + -감 (his). <b>긴장감이 돌다 / 있다</b>, 긴장감을 느끼다.","면접장에는 **긴장감**이 가득했어요.","Mülakat salonu gerginlikle doluydu."],
["사교성","sosyallik, girişkenlik","사교 + -성 (nitelik). <b>사교성이 좋다 / 있다</b>.","그는 **사교성**이 좋아서 누구와도 금방 친해져요.","Çok sosyal biri, o yüzden herkesle hemen kaynaşıyor."],
["영향력","etki gücü, nüfuz","영향 + -력. <b>영향력이 크다 / 있다</b>, 인플루언서 = 영향력 있는 사람.","SNS의 **영향력**이 점점 커지고 있어요.","Sosyal medyanın etkisi giderek artıyor."],
["책임감","sorumluluk duygusu","책임 + -감. <b>책임감이 강하다 / 있다</b>.","그녀는 **책임감**이 강해서 맡은 일을 끝까지 해요.","Sorumluluk duygusu güçlü olduğu için üstlendiği işi sonuna kadar götürür."],
["친밀감","yakınlık duygusu, samimiyet","친밀 + -감. <b>친밀감을 느끼다 / 높이다</b>.","자주 만나면 **친밀감**이 생겨요.","Sık görüşünce bir yakınlık duygusu oluşur."],
["판단력","muhakeme gücü, sağduyu","판단 + -력. <b>판단력이 좋다 / 뛰어나다 / 흐려지다</b>.","너무 피곤하면 **판단력**이 떨어져요.","Çok yorgun olunca muhakeme gücü düşer."],
["편리성","kullanışlılık, kolaylık","편리 + -성. Resmî ve analitik. 편리함 daha gündelik.","간편 결제는 **편리성** 때문에 인기가 많아요.","Kolay ödeme, kullanışlılığı sayesinde çok popüler."]]}]});
